    const key = pk ? pk + "|" + (a.rate_end_date || "") : "";
    if (!key) { a.__dupes = 1; rateErcMerged.push(a); return; }
    if (!rateErcSeen.has(key)) { a.__dupes = 1; rateErcSeen.set(key, a); rateErcMerged.push(a); return; }
    rateErcSeen.get(key).__dupes++;
