/* Move a case to a new stage. Shared by desktop drag-and-drop (the drop handler above)
   and the per-card "Move to stage" dropdown, which gives touch/mobile users — for whom
   HTML5 drag-and-drop does not fire — a working way to progress a case from the board. */
/* BUILD 7c — moveCaseToStage stays THE single stage-move path, but now takes an options bag so the
   bulk-move flow can route each case through it while suppressing per-row toasts/reloads and doing
   its own single confirm. Returns a status string ("moved" | "reopened" | "blocked" | "noop" |
   "cancelled" | "error") so the caller can tally results; single-call behaviour (toast + reload) is unchanged when
   no opts are passed. opts.cRow lets bulk pass a pre-fetched row to avoid a per-case round-trip. */
window.moveCaseToStage = async function (caseId, targetStage, opts = {}) {
  const { silent = false, skipReload = false, skipConfirm = false, cRow: preRow = null } = opts;
  if (!caseId || !targetStage) return "noop";
  let cRow = preRow;
  if (!cRow) {
    // G6-10 — the identity columns come along so the result toast can say WHICH case moved.
    const propOn = await propAddrSupported();
    /* R9-1 — client_id/assigned_to and (where m11 is there) the referrer come along too, so a
       completion can offer the thank-you task without a second round-trip, and so the confirm
       below can say whether one will be offered at all. */
    const refOn = await referrerSupported();
    cRow = (await db.from("cases")
      /* R12b · W-30 — offer_expiry_date comes along so the Offer stage-entry prompt can tell
         "already recorded" from "never asked". A base column (the case form has always written it
         unconditionally), so naming it costs no feature detection. */
      .select("id,client_id,assigned_to,stage,protection_status,completed_at,case_kind,lender,offer_expiry_date" + (propOn ? ",property_address" : "") + (refOn ? ",referrer_client_id" : "") + ",clients!client_id(first_name,last_name)")
      .eq("id", caseId).single()).data;
  }
  if (cRow && cRow.stage === targetStage) return "noop"; // no-op (e.g. dropped back on the same column)
  if (cRow && protectionGateBlocks(cRow, targetStage)) {
    if (!silent) {
      toast("🛡️ Record the protection conversation before submitting — set a protection status");
      if (!skipReload) loadPipeline(); // put the card back
      /* R5-34 — the refusal used to be the end of it: a toast, the card snapped back, and the field
         that would unblock the move was three clicks away inside a collapsed drawer. Open the case
         ON the protection select so the block routes straight to its own fix. */
      await openCase(caseId, { revealProtection: true });
    }
    return "blocked";
  }
  const reopening = !!cRow && isReopening(cRow.stage, targetStage);
  const caseName = (cRow && cRow.clients ? [cRow.clients.first_name, cRow.clients.last_name].filter(Boolean).join(" ") : "") || "this case";
  /* R5-20 / B3 — Not Proceeding now costs a reason, not an OK. The bulk path asks once for the
     whole batch and passes it in (opts.lost); an interactive move asks here. Cancelling the
     capture aborts the move exactly as cancelling the old confirm did. */
  let lost = opts.lost || null;
  if (targetStage === "not_proceeding" && !skipConfirm) {
    lost = await promptLostReason(`Moving ${caseName} to Not Proceeding`);
    if (!lost) { if (!skipReload) loadPipeline(); return "cancelled"; }
  }
  if (!skipConfirm && (targetStage === "completed" || reopening)) {
    const nm = caseName;
    const msg = reopening
      // T1-8 — reopening a settled case had no confirm at all: dragging a Completed card back to a
      // live column silently undid its completion. Name what is being undone.
      ? `REOPEN ${nm}? It is currently ${STAGE_LABEL[cRow.stage] || cRow.stage} — moving it to ${STAGE_LABEL[targetStage] || targetStage} clears its completion date and puts it back in the live pipeline.`
      : targetStage === "completed"
      // T1-honestfix (defect 8) — nothing queues automatically on this move: no email_queue row,
      // no case_events note, no retention case. Checked against app.js and mock-supabase.js — the
      // only completion-related emails are the ones an adviser sends by hand from the case (fee
      // request, review request, rate-end reminder), and there is no code path anywhere that
      // creates a retention case. Say what actually happens, not what would be nice.
      /* R9-1 — and the one thing that IS now offered, named before it happens rather than
         appearing as a surprise second dialog. Still nothing automatic: the next prompt asks,
         and Cancel there leaves the referrer's file untouched. */
      ? `Move ${nm} to Completed? Nothing is sent or set up automatically — email the fee request, review request and rate-end reminder from the case yourself, and set a reminder for retention when the rate ends.`
        + (cRow && cRow.referrer_client_id ? `\n\nThis client was referred, so you will be asked next whether to add a thank-you task on the referrer's case. No email is sent to anybody either way.` : "")
      : "";
    if (msg && !confirm(msg)) { if (!skipReload) loadPipeline(); return "cancelled"; } // abort — snap the card back
  }
  /* R12b · W-30 — the stage-entry prompt, opt-in and interactive-only (see promptStageEntry's
     header for exactly which call sites pass this and why every other one must not). It runs
     LAST, after the protection gate and the lost/completed confirms, so a move that was going to
     be refused or abandoned never asks for a lender first. */
  let stageEntry = {};
  if (opts.promptStageEntry && !skipConfirm) {
    stageEntry = await promptStageEntry(targetStage, cRow, caseName);
    if (!stageEntry) { if (!skipReload) loadPipeline(); return "cancelled"; }
  }
  // T1-7 — completed_at is the basis every completion report counts on, and nothing but the
  // importer ever wrote it. Stamp it on the way in, clear it on the way out.
  const patch = { stage: targetStage };
  if (stageEntry.patch) Object.assign(patch, stageEntry.patch);   // R12b · W-30 — blank stays blank
  if (targetStage === "completed") { if (!cRow || !cRow.completed_at) patch.completed_at = new Date().toISOString(); }
  else if (cRow && cRow.stage === "completed") patch.completed_at = null;
  if (lost && targetStage === "not_proceeding") { patch.lost_reason = lost.reason; patch.lost_detail = lost.note || null; }
  let { error } = await db.from("cases").update(patch).eq("id", caseId);
  // Feature-detect M2: an older database has no lost-reason columns — the move still happens and
  // the reason still reaches the case history as a note, it just isn't queryable yet.
  let lostColsMissing = false;
  if (error && lost && isMissingColumnError(error)) {
    lostColsMissing = true;
    delete patch.lost_reason; delete patch.lost_detail;
    ({ error } = await db.from("cases").update(patch).eq("id", caseId));
  }
  if (error) { if (!silent) toast("Error: " + error.message); return "error"; }
  if (lost) {
    const { error: nErr } = await db.from("case_notes")
      .insert({ case_id: caseId, body: lostReasonNoteBody(lost), created_by: (ME && ME.id) || null });
    if (nErr && !silent) toast("Case moved, but the reason note could not be saved: " + nErr.message);
  }
  /* R9-1 — THE ONE EVENT the thank-you hangs off: a case with a referrer arriving at Completed.
     Deliberately AFTER the update has succeeded (a courtesy task for a completion that did not
     happen is worse than no task), and only on a genuine arrival — a re-save of an already
     completed case is not a completion, and the idempotency check inside catches the rest. It is
     suppressed on the bulk path (silent) for the same reason bulk suppresses every other prompt:
     one dialog per case, in the middle of a fifty-case move, is not a prompt, it is a wall. */
  /* R12b · W-30 — the DIP chase task, only ever from the "Save & advance" path and only when the
     operator left the box ticked. Written AFTER the stage move has succeeded, for the same reason
     the referral thank-you is: a chase task for a DIP the case never reached is litter. Idempotent
     on its own title so pressing Advance twice cannot leave two. */
  let stageEntryTaskNote = "";
  if (stageEntry.task) {
    const existing = await softRows(db.from("case_tasks").select("id,title,done_at").eq("case_id", caseId));
    if (existing.some((t) => !t.done_at && String(t.title || "").trim() === stageEntry.task.title)) {
      stageEntryTaskNote = ` · a “${stageEntry.task.title}” task was already open`;
    } else {
      const { error: tErr } = await db.from("case_tasks").insert({
        case_id: caseId, title: stageEntry.task.title, due_date: stageEntry.task.due_date,
        assigned_to: (cRow && cRow.assigned_to) || (ME && ME.id) || null,
      });
      stageEntryTaskNote = tErr
        ? ` · the “${stageEntry.task.title}” task could not be created: ${tErr.message}`
        : ` · “${stageEntry.task.title}” task added for ${fmtD(stageEntry.task.due_date)}`;
    }
  }
  let refResult = null;
  if (targetStage === "completed" && !silent && (!cRow || cRow.stage !== "completed")) {
    refResult = await maybeQueueReferralThankYou(caseId, cRow, { quiet: true });
  }
  if (!silent) {
    // If the case just left the focused segment its card vanishes from this view —
    // name the segment it landed in so nobody thinks the deal disappeared.
    let where = "";
    if (pipelineSegment !== "all" && !inSegment(targetStage, pipelineSegment)) {
      const segNames = { new: "New business", current: "Current", completed: "Completed & closed" };
      const destSeg = Object.keys(SEGMENT_STAGES).find((k) => SEGMENT_STAGES[k].includes(targetStage));
      if (destSeg) where = " — now in " + (segNames[destSeg] || destSeg);
    }
    /* G6-10 — "Moved to Offer" named nothing at all, on the one screen where a landlord has five
       cards that differ only by building. The retention flow in the same round already says
       "Retention case created ✓ — 8 Grand Ave"; this now matches it. The identity is built from the
       row as it was BEFORE the move (its stage is the old one, so only the property/type/lender part
       is used) — the stage the case landed in is already the subject of the sentence. */
    const movedWhat = [propLabel(cRow), cRow && cRow.case_kind ? caseTypeLabel(cRow) : null, cRow && cRow.lender]
      .filter(Boolean).join(" · ");
    toast("Moved to " + (STAGE_LABEL[targetStage] || targetStage) + (movedWhat ? " — " + movedWhat : "") + where
      + (lostColsMissing ? " · reason kept as a note only (run migration M2)" : "")
      /* R9-1 — the referral outcome rides on THIS toast rather than firing its own a moment
         earlier and being overwritten by it. Both outcomes are worth a sentence: a task was
         created on somebody else's file, or one deliberately was not and here is why. */
      + (refResult && refResult.message ? " · " + refResult.message : "")
      /* R12b · W-30 — what the entry prompt actually wrote, named on the move's own toast rather
         than in a second one that would overwrite it. */
      + (stageEntry.patch && stageEntry.patch.lender ? ` · lender set to ${stageEntry.patch.lender}` : "")
      + (stageEntry.patch && stageEntry.patch.offer_expiry_date ? ` · offer expiry ${fmtD(stageEntry.patch.offer_expiry_date)}` : "")
      // R13 · M-11 — the toast names everything the prompt actually wrote, or it is not a receipt.
      + (stageEntry.patch && stageEntry.patch.offer_issued_date ? ` · offer issued ${fmtD(stageEntry.patch.offer_issued_date)}` : "")
      + stageEntryTaskNote);
    if (!skipReload) loadPipeline();
  }
  return reopening ? "reopened" : "moved";
};
/* BUILD 7c — bulk stage move (pipeline table). One confirm summarising the whole batch, then each
   case routed through moveCaseToStage (silent, no reload).
   T1-8 — the rows are now fetched and pre-classified BEFORE the confirm, so the dialog states the
   real outcome of the batch rather than a bare count; every selected case lands in exactly one of
   four buckets so the result toast adds up to the selection size; and a batch that would resurrect
   settled cases needs the typed keyword (the confirmHardDelete pattern) rather than a plain OK. */
async function bulkMoveStage(targetStage) {
  const ids = [...pipeSel];
  if (!ids.length || !targetStage) return;
  const label = STAGE_LABEL[targetStage] || targetStage;
  const propOn = await propAddrSupported();
  const { data: rows } = await db.from("cases")
    .select("id,stage,protection_status,completed_at,case_kind,lender" + (propOn ? ",property_address" : "") + ",clients!client_id(first_name,last_name)")
    .in("id", ids);
  const byId = {}; (rows || []).forEach((r) => (byId[r.id] = r));
  // Classify exactly the way moveCaseToStage will, so the confirm can't promise one thing and the
  // result report another.
  const plan = { move: 0, blocked: 0, already: 0, reopen: 0 };
  // G6-10 — and keep the ROWS per bucket, not just the tallies, so the confirm can name the cases
  // it is about to reopen or refuse instead of leaving the operator to guess which of five.
  const bucketRows = { move: [], blocked: [], already: [], reopen: [] };
  ids.forEach((id) => {
    const r = byId[id];
    let bucket;
    if (r && r.stage === targetStage) bucket = "already";
    else if (r && protectionGateBlocks(r, targetStage)) bucket = "blocked";
    else if (r && isReopening(r.stage, targetStage)) bucket = "reopen";
    else bucket = "move";
    plan[bucket]++;
    if (r) bucketRows[bucket].push(r);
  });
  const namedBucket = (key, heading) => {
    const list = bucketRows[key];
    if (!list.length) return "";
    return `\n\n${heading}:\n${list.slice(0, 6).map((r) => "· " + bulkCaseLabel(r)).join("\n")}`
      + (list.length > 6 ? `\n· and ${list.length - 6} more` : "");
  };
  /* R5-20 / B3 — one reason for the batch, captured BEFORE the confirm so the confirm can name it
     and nobody stamps ten cases with a reason they never saw. Backing out aborts the whole move. */
  let lost = null;
  if (targetStage === "not_proceeding" && plan.move) {
    lost = await promptLostReason(`Moving ${plan.move} case${plan.move === 1 ? "" : "s"} to Not Proceeding`);
    if (!lost) return;
  }
  const head = `Move ${ids.length} case${ids.length === 1 ? "" : "s"} to ${label}?\n\n` +
    `${plan.move} will move\n` +
    `${plan.blocked} are blocked (no protection status)\n` +
    `${plan.already} are already in ${label}\n` +
    `${plan.reopen} are Completed/Not Proceeding and will be REOPENED` +
    namedBucket("move", "Moving") + namedBucket("reopen", "REOPENING") +
    namedBucket("blocked", "Blocked (no protection status)") + namedBucket("already", `Already in ${label}`) +
    (lost ? `\n\nReason recorded on every case moved: ${lost.label}${lost.note ? " — " + lost.note : ""}\nTheir open tasks will be closed.` : "");
  if (plan.reopen) {
    const typed = prompt(
      `${head}\n\n` +
      "Reopening puts settled cases — completion dates, fees and retention — back into the live " +
      "pipeline, and there is no undo.\n\nType REOPEN to confirm:"
    );
    if (typed == null || typed.trim().toUpperCase() !== "REOPEN") return;
  } else if (!confirm(head)) return;
  let moved = 0, reopened = 0, blocked = 0, noop = 0, err = 0;
  const movedIds = [];
  for (const id of ids) {
    const res = await moveCaseToStage(id, targetStage, { silent: true, skipReload: true, skipConfirm: true, cRow: byId[id], lost });
    if (res === "moved") { moved++; movedIds.push(id); }
    else if (res === "reopened") reopened++;
    else if (res === "blocked") blocked++;
    else if (res === "error") err++;
    else noop++;
  }
  /* B3 — a closed case must not keep nagging. Production's cancel_retention_touches trigger closes
     the open tasks of a case that stops, so the bulk path does the same thing here and the two
     agree: the cases disappear from the board AND from everybody's task list. */
  let tasksClosed = 0;
  if (lost && movedIds.length) {
    const { data: closed, error: tErr } = await db.from("case_tasks")
      .update({ done_at: new Date().toISOString() }).in("case_id", movedIds).is("done_at", null).select("id");
    if (!tErr) tasksClosed = (closed || []).length;
  }
  // All four buckets, always: the old summary dropped the no-ops entirely, so the numbers never
  // added up to what was selected.
  let msg = `${moved} moved · ${reopened} reopened · ${blocked} blocked (protection) · ${noop} already in ${label}`;
  if (tasksClosed) msg += ` · ${tasksClosed} open task${tasksClosed === 1 ? "" : "s"} closed`;
  if (err) msg += ` · ${err} error${err === 1 ? "" : "s"}`;
  toast(msg);
  pipeSel.clear();
  loadPipeline();
}
/* BUILD 7c — bulk assign adviser (pipeline table). Sequential awaited updates with an error tally. */
async function bulkAssignCases(adviserId, reloadFn) {
  const ids = [...pipeSel];
  if (!ids.length || !adviserId) return;
  const name = adviserId === authUid ? "you" : staffName(adviserId);
  if (!confirm(`Assign ${ids.length} case${ids.length === 1 ? "" : "s"} to ${adviserId === authUid ? "yourself" : name}?`)) return;
  let ok = 0, err = 0;
  for (const id of ids) {
    const { error } = await db.from("cases").update({ assigned_to: adviserId }).eq("id", id);
    if (error) err++; else ok++;
  }
  let msg = `${ok} case${ok === 1 ? "" : "s"} assigned to ${name}`;
  if (err) msg += `, ${err} error${err === 1 ? "" : "s"}`;
  toast(msg);
  pipeSel.clear();
  (reloadFn || loadPipeline)();
}
/* ---------- R5 Batch 5 · S3a — bulk "Queue rate-end reminders" (pipeline table) ----------
   The rate-end sweep is the one job that is genuinely a batch: twenty clients whose fixed rate
   expires this quarter, one reminder each. Doing it case by case means twenty modal round-trips.
   Two rules make the bulk version safe:
     • QUEUED ONLY. This never calls runAutomation — R5-1's discipline says a send is a deliberate,
       scoped act, and "select 20 rows" is not a mandate to email 20 clients this instant. The rows
       sit in email_queue and go out on the next automation run (or a deliberate Send-all).
     • Every queued reminder leaves a follow-up task behind (R5-13, same title/date/assignee rule as
       the per-case queueEmail path), so a client who doesn't reply is still chased.
   Cases with no client email or no rate end date are named in the confirm and skipped, never
   half-written. */
/* G1I-D7 — every other round-5 action button guards itself against a second invocation while the
   first is still running (startRetentionCase, protQueueEmail, queueEmail, #run-now-btn,
   #deact-reassign); the two bulk-bar actions did not. A key-repeat on the focused button — two
   Enter presses — started two overlapping runs: both read the case list before either stamped, so
   the second confirmation was textually identical (no "⚠ already been reminded once" warning) and
   every selected client got TWO reminder emails and TWO chase tasks, while the single-slot toast
   showed only one summary. A real mouse double-click happened to be serialised by the blocking
   confirm(); the keyboard path was not. */
let bulkBusy = false;
function setBulkBusy(on) {
  bulkBusy = on;
  ["#pipe-bulk-rate", "#pipe-bulk-retention", "#pipe-bulk-task", "#pipe-bulk-stage", "#pipe-bulk-adviser", "#pipe-bulk-clear"]
    .forEach((sel) => { const el = $(sel); if (el) el.disabled = on; });
}
async function bulkQueueRateReminders() {
  const ids = [...pipeSel];
  if (!ids.length) return;
  if (bulkBusy) return;
  setBulkBusy(true);
  try {
    await bulkQueueRateRemindersRun(ids);
  } finally { setBulkBusy(false); }
}
/* G6-02 / G6-10 — the bulk bar is the ONE list of cases round 6's canonical identifier never
   reached, and on a multi-property client that was not cosmetic. Every confirm line, skip reason
   and error report was built from the client's NAME, so a sweep over Gareth Pollard's five
   buy-to-lets reported "Gareth Pollard, Gareth Pollard, Gareth Pollard" — and the retry pruning
   matched the failure list against that same name, so ONE failed case re-selected ALL of that
   client's selected cases and the second press re-queued the one that had already worked while
   still never touching the one that failed. Failures are collected as case IDS now, and named with
   the same property · type · lender · stage identity the rest of the app uses. */
function bulkCaseLabel(c) {
  const who = [c.clients?.first_name, c.clients?.last_name].filter(Boolean).join(" ") || "this client";
  const what = caseIdentityLabel(c);
  return what ? `${who} — ${what}` : who;
}
/* ==========================================================================
   R7-2 — BULK "START RETENTION CASE" from the pipeline table.

   A rate-end review is done off this table, a dozen rows at a time; until now the
   only route to the retention flow was one button on one row of one Today panel,
   so working a list of twelve meant twelve trips to the dashboard.

   THE DESIGN RULE HERE: this is a loop over the EXISTING single-case flow, not a
   reimplementation of it. Every per-case confirm still appears — including the
   sold-property warning that names another client's case on the same building,
   and the "no property address is recorded" line — because those are the whole
   point of that dialog and a bulk verb that skipped them would be a quietly
   more dangerous flow wearing a familiar name. What the bulk verb adds is a
   PRE-FLIGHT (which of the selected rows can even do this, and why not) and a
   TALLY at the end, in one message, because six toasts in a row means five of
   them were never seen (the G1I-R7 finding).
   ========================================================================== */
async function bulkStartRetention() {
  const ids = [...pipeSel];
  if (!ids.length) return;
  if (bulkBusy) return;
  setBulkBusy(true);
  try { await bulkStartRetentionRun(ids); } finally { setBulkBusy(false); }
}
async function bulkStartRetentionRun(ids) {
  const propOn = await propAddrSupported();
  const { data: rows, error } = await db.from("cases")
    .select("id,client_id,stage,rate_end_date,case_kind,lender,retention_source_case_id"
      + (propOn ? ",property_address" : "") + ",clients!client_id(first_name,last_name)")
    .in("id", ids);
  if (error) return toast("Error: " + error.message);
  const nameOf = bulkCaseLabel;
  // Which of these already have a successor — one query, not one per row.
  const { data: succ } = await db.from("cases").select("retention_source_case_id").in("retention_source_case_id", ids);
  const hasSuccessor = new Set((succ || []).map((r) => r.retention_source_case_id));
  const today = localDateStr();
  const eligible = [], skipped = [];
  (rows || []).forEach((c) => {
    if (c.stage !== "completed") skipped.push(`${nameOf(c)} (not completed)`);
    else if (!c.rate_end_date) skipped.push(`${nameOf(c)} (no rate-end date)`);
    else if (hasSuccessor.has(c.id)) skipped.push(`${nameOf(c)} (already has a retention case)`);
    else {
      /* R7-2 — the same nine-month rule the Rate & ERC panel applies to its button. Starting a
         retention case a year out creates a live enquiry, a call task and a queued client email
         for a conversation that cannot usefully happen yet; doing twelve of them at once is how a
         pipeline fills with work nobody can do. */
      const daysOut = Math.round((new Date(c.rate_end_date + "T12:00:00") - new Date(today + "T12:00:00")) / 86400000);
      if (daysOut > 274) skipped.push(`${nameOf(c)} (rate ends in ${Math.round(daysOut / 30)} months — too early)`);
      else eligible.push(c);
    }
  });
  if (!eligible.length) {
    return toast(skipped.length
      ? `Nothing to start — all ${skipped.length} selected case${skipped.length === 1 ? " is" : "s are"} ineligible (${skipped.slice(0, 3).join("; ")}${skipped.length > 3 ? `; and ${skipped.length - 3} more` : ""})`
      : "Nothing to start");
  }
  eligible.sort((a, b) => (a.rate_end_date < b.rate_end_date ? -1 : 1));
  if (!confirm([
    `Start a retention case for ${eligible.length} of the ${ids.length} selected case${ids.length === 1 ? "" : "s"}?`,
    "",
    `You will be asked about each one separately — the same confirmation the single-case button shows, including any warning that another client holds a later case on the same property. Cancel on an individual case skips just that one.`,
    "",
    "Starting with:",
    ...eligible.slice(0, 8).map((c) => `· ${nameOf(c)} — rate ends ${fmtD(c.rate_end_date)}`),
    ...(eligible.length > 8 ? [`· and ${eligible.length - 8} more`] : []),
    ...(skipped.length ? ["", `Skipped (${skipped.length}): ${skipped.slice(0, 5).join("; ")}${skipped.length > 5 ? `; and ${skipped.length - 5} more` : ""}`] : []),
  ].join("\n"))) return;

  let created = 0, cancelled = 0, failed = 0, partial = 0;
  const failures = [], partials = [];
  for (const c of eligible) {
    const res = await startRetentionCase(c.id, null, { silent: true });
    const st = (res && res.status) || "error";
    if (st === "created") created++;
    else if (st === "created_with_warnings") { created++; partial++; partials.push(nameOf(c)); }
    else if (st === "cancelled") cancelled++;
    else if (st === "skipped") { failed++; failures.push(`${nameOf(c)} — ${res.message}`); }
    else { failed++; failures.push(`${nameOf(c)} — ${(res && res.message) || "unknown error"}`); }
  }
  /* ONE sentence at the end, naming every outcome that is not a clean success. A tally that says
     only "6 created" when two of them failed to queue their reminder is the failure mode the
     single-case flow already fixed for itself. */
  let out = `${created} retention case${created === 1 ? "" : "s"} created`;
  if (partial) out += ` (${partial} with problems: ${partials.slice(0, 3).join(", ")}${partials.length > 3 ? ` and ${partials.length - 3} more` : ""} — open them and check the note, task and queued email)`;
  if (cancelled) out += ` · ${cancelled} cancelled by you`;
  if (skipped.length) out += ` · ${skipped.length} skipped as ineligible`;
  if (failed) out += ` · ${failed} failed: ${failures.slice(0, 2).join("; ")}${failures.length > 2 ? ` and ${failures.length - 2} more` : ""}`;
  toast(out);
  if (created) {
    pipeSel.clear();
    loadPipeline();
    if (!$("#page-dashboard").classList.contains("hidden")) loadDashboard();
  }
}
async function bulkQueueRateRemindersRun(ids) {
  // The identity needs the property column, which an un-migrated database does not have: name it
  // only where it exists, exactly as loadPropContext does, so the sweep cannot 42703 on M7.
  const propOn = await propAddrSupported();
  const { data: rows, error } = await db.from("cases")
    .select("id,client_id,rate_end_date,assigned_to,rate_reminder_queued_at,case_kind,lender,stage"
      + (propOn ? ",property_address" : "") + ",clients!client_id(first_name,last_name,email)")
    .in("id", ids);
  if (error) return toast("Error: " + error.message);
  const nameOf = bulkCaseLabel;
  const eligible = [], skipped = [];
  (rows || []).forEach((c) => {
    if (!(c.clients && c.clients.email)) skipped.push(`${nameOf(c)} (no email)`);
    else if (!c.rate_end_date) skipped.push(`${nameOf(c)} (no rate-end date)`);
    else eligible.push(c);
  });
  if (!eligible.length) {
    return toast(skipped.length
      ? `Nothing to queue — ${skipped.length} selected case${skipped.length === 1 ? " has" : "s have"} no email or no rate-end date`
      : "Nothing to queue");
  }
  // Not a skip reason (the operator may deliberately be re-chasing), but they deserve to know
  // before they send a second reminder to the same client.
  const already = eligible.filter((c) => c.rate_reminder_queued_at);
  const chaseDue = localDateStr(Date.now() + 7 * 86400000);
  const confirmMsg = `Queue ${eligible.length} rate-end reminder${eligible.length === 1 ? "" : "s"}?`
    + (skipped.length ? ` (${skipped.length} skipped: no email/no rate-end date)` : "")
    + `\n\nThey send with the next automation run — nothing is sent now.`
    + `\nEach one also gets a follow-up task due ${fmtD(chaseDue)}.`
    + (skipped.length ? `\n\nSkipped: ${skipped.slice(0, 5).join(", ")}${skipped.length > 5 ? ` and ${skipped.length - 5} more` : ""}` : "")
    + (already.length ? `\n\n⚠ ${already.length} of these ${already.length === 1 ? "has" : "have"} already been reminded once — they will be reminded again:\n${already.slice(0, 5).map((c) => "· " + nameOf(c)).join("\n")}${already.length > 5 ? `\n· and ${already.length - 5} more` : ""}` : "")
    /* G6-10 — the batch has to say WHICH cases, not just how many. On a landlord with five
       properties "2 rate-end reminders" and "1 has already been reminded" name nothing at all. */
    + `\n\nQueueing for:\n${eligible.slice(0, 8).map((c) => "· " + nameOf(c)).join("\n")}${eligible.length > 8 ? `\n· and ${eligible.length - 8} more` : ""}`;
  if (!confirm(confirmMsg)) return;
  let queued = 0, tasks = 0, raced = 0;
  // G1I-B1/B3/B5 — every part of the promise this button made is now accounted for by name. The
  // old summary counted only the queue insert and the task insert, so a stamp that never landed
  // (case still reads "Reminder pending", still eligible for the same sweep, never warned about on
  // the next run) and a chase task that never existed both read as a clean success.
  const failedQueue = [], failedTask = [], failedStamp = [];
  for (const c of eligible) {
    /* G1I-D7 — read the stamp again immediately before writing. Two overlapping runs (or a second
       operator on the same list) both read `eligible` before either stamped anything; without this
       re-read the second run cheerfully queues a duplicate reminder to the same client. */
    const { data: fresh } = await db.from("cases").select("rate_reminder_queued_at").eq("id", c.id).single();
    if (fresh && fresh.rate_reminder_queued_at && !c.rate_reminder_queued_at) { raced++; continue; }
    const { error: qErr } = await db.from("email_queue").insert({
      case_id: c.id, client_id: c.client_id, email_type: "rate_end_reminder", to_email: c.clients.email,
    });
    if (qErr) { failedQueue.push({ id: c.id, label: nameOf(c) }); continue; }
    queued++;
    const { error: sErr } = await db.from("cases").update({ rate_reminder_queued_at: new Date().toISOString() }).eq("id", c.id);
    if (sErr) failedStamp.push({ id: c.id, label: nameOf(c) });
    const { error: tErr } = await db.from("case_tasks").insert({
      case_id: c.id,
      title: `Follow up rate-end reminder — ${(c.clients.first_name || "client").trim()}`,
      due_date: chaseDue,
      assigned_to: c.assigned_to || (ME && ME.id) || null,
      created_by: (ME && ME.id) || null,
    });
    if (tErr) failedTask.push({ id: c.id, label: nameOf(c) }); else tasks++;
  }
  const err = failedQueue.length + failedTask.length + failedStamp.length;
  const names = (list) => list.slice(0, 4).map((f) => f.label).join(", ") + (list.length > 4 ? ` and ${list.length - 4} more` : "");
  const detail = [];
  if (failedQueue.length) detail.push(`no reminder was queued for ${names(failedQueue)}`);
  if (failedTask.length) detail.push(`the follow-up task failed for ${names(failedTask)} — nothing holds the next step`);
  if (failedStamp.length) detail.push(`${names(failedStamp)} could not be marked as reminded, so ${failedStamp.length === 1 ? "it still reads" : "they still read"} “Reminder pending” and will be offered again`);
  let msg = `${queued} reminder${queued === 1 ? "" : "s"} queued · ${tasks} follow-up task${tasks === 1 ? "" : "s"} · 0 sent`;
  if (skipped.length) msg += ` · ${skipped.length} skipped`;
  if (raced) msg += ` · ${raced} already reminded by another run`;
  if (err) msg += ` · ${err} error${err === 1 ? "" : "s"}: ${detail.join("; ")}`;
  toast(msg);
  /* Leave anything that failed selected, so the retry is targeted instead of a re-run over the
     whole selection (which would duplicate everything that did work). G6-02 — by ID. Pruning by
     client NAME re-selected every case belonging to a client any of whose cases failed, which on a
     multi-property landlord is the exact duplication this line exists to prevent. */
  const stillSelected = new Set([...failedQueue, ...failedTask, ...failedStamp].map((f) => f.id));
  pipeSel.clear();
  stillSelected.forEach((id) => pipeSel.add(id));
  loadPipeline();
}
/* ---------- R5 Batch 5 · S3b — bulk "Add task…" (pipeline table) ----------
   One title, one due date, one task per selected case — each landing on THAT case's adviser (not
   on whoever ran the batch), so a sweep of "chase the solicitor" tasks arrives in the right lists. */
function promptBulkTask(n) {
  const today = localDateStr(new Date());
  const html = `
    <h3>Add a task to ${n} case${n === 1 ? "" : "s"}</h3>
    <p class="panel-sub">One task per selected case. Each one is assigned to that case's adviser — or to you where the case has nobody on it.</p>
    <label>Task<input id="btask-title" type="text" placeholder="e.g. Chase the solicitor" maxlength="120"></label>
    <div class="due-chips" style="margin-top:10px;">
      <span class="due-chips-lbl">Due:</span>
      <button type="button" class="btn btn-sm btask-chip" data-days="0">Today</button>
      <button type="button" class="btn btn-sm btask-chip" data-days="3">+3 days</button>
      <button type="button" class="btn btn-sm btask-chip" data-days="7">+1 week</button>
    </div>
    <label style="margin-top:10px;">Date<input type="date" id="btask-due" value="${today}"></label>
    <div class="ovl-err" id="btask-err"></div>
    <div class="modal-actions">
      <div></div>
      <div class="right">
        <button type="button" class="btn" id="btask-cancel">Cancel</button>
        <button type="button" class="btn btn-primary" id="btask-ok">Add ${n} task${n === 1 ? "" : "s"}</button>
      </div>
    </div>`;
  return openOverlay(html, (finish, box) => {
    const dateInput = box.querySelector("#btask-due");
    box.querySelectorAll(".btask-chip").forEach((b) => b.onclick = () => {
      const d = new Date();
      d.setDate(d.getDate() + Number(b.dataset.days || 0));
      dateInput.value = localDateStr(d);
    });
    box.querySelector("#btask-cancel").onclick = () => finish(null);
    box.querySelector("#btask-ok").onclick = () => {
      const title = (box.querySelector("#btask-title").value || "").trim();
      if (!title) { box.querySelector("#btask-err").textContent = "Give the task a title."; box.querySelector("#btask-title").focus(); return; }
      finish({ title, due: dateInput.value || null });
    };
  });
}
async function bulkAddTask() {
  const ids = [...pipeSel];
  if (!ids.length) return;
  if (bulkBusy) return;                       // G1I-D7 — same in-flight guard as the reminder sweep
  setBulkBusy(true);
  try { await bulkAddTaskRun(ids); } finally { setBulkBusy(false); }
}
async function bulkAddTaskRun(ids) {
  // G1I-B5 — the client's name is fetched so a failure can be NAMED. Reporting "1 error" over a
  // selection that is then cleared left the operator with no way to tell which of five clients
  // missed its task; the only recovery was to re-run over all five and create four duplicates.
  // G6-10 — and the failure is named with the case's identity, not just the client's name: "no task
  // for Gareth Pollard" says nothing when three of the selected cases are his.
  const propOn = await propAddrSupported();
  const { data: rows, error } = await db.from("cases")
    .select("id,assigned_to,case_kind,lender,stage" + (propOn ? ",property_address" : "") + ",clients!client_id(first_name,last_name)")
    .in("id", ids);
  if (error) return toast("Error: " + error.message);
  const nameOf = bulkCaseLabel;
  const picked = await promptBulkTask((rows || []).length || ids.length);
  if (!picked) return;
  let ok = 0;
  const failed = [];
  for (const c of rows || []) {
    const { error: tErr } = await db.from("case_tasks").insert({
      case_id: c.id, title: picked.title, due_date: picked.due,
      assigned_to: c.assigned_to || (ME && ME.id) || null,
      created_by: (ME && ME.id) || null,
    });
    if (tErr) failed.push({ id: c.id, name: nameOf(c) }); else ok++;
  }
  let msg = `${ok} task${ok === 1 ? "" : "s"} added (“${picked.title}”)${picked.due ? " · due " + fmtD(picked.due) : ""}`;
  if (failed.length) {
    const names = failed.slice(0, 4).map((f) => f.name).join(", ") + (failed.length > 4 ? ` and ${failed.length - 4} more` : "");
    msg += ` · ${failed.length} error${failed.length === 1 ? "" : "s"} — no task for ${names}; ${failed.length === 1 ? "that case is" : "those cases are"} still selected, so pressing Add task again retries only ${failed.length === 1 ? "it" : "them"}`;
  }
  toast(msg);
  pipeSel.clear();
  failed.forEach((f) => pipeSel.add(f.id));   // targeted retry, never a re-run over the whole set
  loadPipeline();
}
/* BUILD 5a — segmented focus control above the pipeline. Counts are live against the current
   adviser/search-filtered set, so each label reflects exactly what that segment would show. */
function renderSegmentControl(filtered) {
  const wrap = $("#pipe-segment");
  if (!wrap) return;
  const count = (seg) => filtered.filter((c) => inSegment(c.stage, seg)).length;
  wrap.innerHTML = SEGMENTS.map(([k, l]) =>
    `<button class="seg-btn${pipelineSegment === k ? " active" : ""}" role="tab" aria-selected="${pipelineSegment === k}" data-seg="${k}">${l} <span class="seg-count">${count(k)}</span></button>`
  ).join("");
  wrap.querySelectorAll(".seg-btn").forEach((b) => (b.onclick = () => setSegment(b.dataset.seg)));
  syncViewToggle();
}
// Switch focus segment. Entering Completed forces the table (its board is meaningless) and
// remembers the prior board/table choice; leaving Completed restores it. Segment change resets
// the stage tab (a tab from another segment would filter to nothing).
function setSegment(seg) {
  if (seg === pipelineSegment) return;
  const leavingCompleted = pipelineSegment === "completed" && seg !== "completed";
  const enteringCompleted = seg === "completed" && pipelineSegment !== "completed";
  if (enteringCompleted) { viewBeforeCompleted = pipelineView; pipelineView = "table"; }
  else if (leavingCompleted && viewBeforeCompleted) { pipelineView = viewBeforeCompleted; viewBeforeCompleted = null; }
  pipelineSegment = seg;
  stageTab = "all";
  if (authUid) lsSet(segStoreKey(authUid), seg);
  loadPipeline();
}
// BUILD 6c — jump straight to a pipeline segment from another page (e.g. the My Day completion-date
// chaser). Mirrors setSegment's leaving-Completed board/table restore, then switches page via nav().
window.gotoPipelineSegment = function (seg) {
  const leavingCompleted = pipelineSegment === "completed" && seg !== "completed";
  if (leavingCompleted && viewBeforeCompleted) { pipelineView = viewBeforeCompleted; viewBeforeCompleted = null; }
  pipelineSegment = seg;
  stageTab = "all";
  if (authUid) lsSet(segStoreKey(authUid), seg);
  nav("pipeline");
};
// Today KPI cards (defect 19) — jump each card to a sensible destination for that number, opening
// and scrolling to the relevant Today drawer where the number already lives on this same page.
function focusDashPanel(panelId, tab) {
  const panel = document.getElementById(panelId);
  if (!panel) return;
  panel.classList.remove("collapsed");
  dashDrawerTouched[panelId.replace(/-panel$/, "")] = true;
  if (tab) { const tabBtn = panel.querySelector(`.dash-tab[data-tab="${tab}"]`); if (tabBtn) tabBtn.click(); }
  panel.scrollIntoView({ behavior: "smooth", block: "start" });
}
window.kpiGoto = function (which) {
  if (which === "active") return gotoPipelineSegment("all");
  // T1-19 — "completions" is the Today tile (its number lives on Reports); "completed" is the
  // Reports tile, whose rows live in the pipeline's Completed segment.
  if (which === "completed") return gotoPipelineSegment("completed");
  if (which === "completions") return nav("reports");
  nav("dashboard");
  if (which === "rates" || which === "erc") return focusDashPanel("rate-erc-panel");
  if (which === "fees") return focusDashPanel("revenue-panel", "fees");
};
/* T1-19 — Reports rows become doors into the pipeline. Each helper sets exactly one of the two
   board filters and clears the other, so the pipeline that opens contains precisely the set the
   number described — and the filter is visible in the toolbar, so it can be seen and cleared. */
window.reportGotoAdviser = function (who) {
  const sel = $("#board-adviser"), q = $("#board-search");
  if (q) q.value = "";
  if (sel) sel.value = who;
  gotoPipelineSegment("all");
};
window.reportGotoSearch = function (term) {
  const sel = $("#board-adviser"), q = $("#board-search");
  if (sel) sel.value = "all";
  if (q) q.value = term == null ? "" : String(term);
  gotoPipelineSegment("all");
};
window.reportGotoStage = function (stage) {
  const sel = $("#board-adviser"), q = $("#board-search");
  if (sel) sel.value = "all";
  if (q) q.value = "";
  // A single stage is a table view (the board has no single-column mode); stage tabs live there.
  pipelineSegment = "all";
  pipelineView = "table";
  viewBeforeCompleted = null;
  stageTab = stage;
  // Segment persists (as it does from every other segment switch); the forced table view is
  // session-only — the saved board/table preference belongs to the view toggle, not to this click.
  if (authUid) lsSet(segStoreKey(authUid), "all");
  nav("pipeline");
};
// Keep the board/table toggle honest: hidden in Completed (locked to table), otherwise labelled
// for the view it would switch to.
function syncViewToggle() {
  const btn = $("#view-toggle");
  if (!btn) return;
  btn.style.display = pipelineSegment === "completed" ? "none" : "";
  btn.textContent = pipelineView === "board" ? "☰ Table view" : "⊞ Board view";
}
function renderPipelineTable(filtered, stageEntry = {}, propOn = true) {
  $("#board").classList.add("hidden");
  $("#board-hint").classList.add("hidden");
  $("#board-legend").classList.add("hidden");
  $("#stage-tabs").classList.remove("hidden");
  $("#table-wrap").classList.remove("hidden");
  // Stage tabs are scoped to the active segment (segment narrows which stage tabs show).
  const segStages = segmentStageList(pipelineSegment);
  const segFiltered = filtered.filter((c) => inSegment(c.stage, pipelineSegment));
  const counts = {};
  segStages.forEach(([k]) => (counts[k] = segFiltered.filter((c) => c.stage === k).length));
  $("#stage-tabs").innerHTML = [`<button class="stage-tab ${stageTab === "all" ? "active" : ""}" data-stage="all">All (${segFiltered.length})</button>`]
    .concat(segStages.map(([k, l]) => `<button class="stage-tab ${stageTab === k ? "active" : ""}" data-stage="${k}"${k === "decision_in_principle" ? ` title="${TIP_DIP}"` : ""}>${l} (${counts[k]})</button>`)).join("");
  document.querySelectorAll(".stage-tab").forEach((b) => (b.onclick = () => { stageTab = b.dataset.stage; loadPipeline(); }));

  const completedMode = pipelineSegment === "completed";
  let rows = stageTab === "all" ? segFiltered : segFiltered.filter((c) => c.stage === stageTab);
  const val = (c, k) => {
    switch (k) {
      case "client": return [c.clients?.first_name, c.clients?.last_name].filter(Boolean).join(" ").toLowerCase();
      /* R6 — sorting by property groups a landlord's cases by building rather than scattering them
         by date. Sorted on the SHORT label (what the column actually shows) and lower-cased, with
         the no-address rows pushed to the end of an ascending sort instead of clumping at the top
         under an empty string. */
      /* R6-FIX V12/OP-12/R6B-10 \u2014 sorted on STREET, then house number, then outcode; not on the
         rendered label. The label starts with the house number, so a lexical sort ordered a
         portfolio by "12A, 148, 16, 22, 3, 31, 4, 63" \u2014 the number as the key and the street as an
         afterthought, when the question a landlord's book is scanned with is "everything on Ashley
         Road". Numbers compare numerically (padded), so 3 sorts before 31. */
      case "property": return propSortKey(c);
      case "lender": return (c.lender || "").toLowerCase();
      case "rate_percent": return c.rate_percent ?? -1;
      case "broker_fee": return c.broker_fee ?? -1;
      case "loan_amount": return c.loan_amount ?? -1;
      case "assigned": return staffName(c.assigned_to).toLowerCase();
      case "days_in_stage": return daysSince(stageEntry[c.id]) ?? -1;
      default: return c[k] ?? "";
    }
  };
  // Completion-focused table: its own columns, defaulting to newest-completed first (falls back
  // to completed_at desc whenever the active sort key isn't one of its columns).
  /* R6 — Property sits immediately after Client in both tables: it is the second half of "which
     case is this?", and anywhere else leaves a portfolio landlord's five rows identical for the
     first two columns. Omitted entirely (not rendered empty) on a database that has not taken
     migration M7 — same discipline as the case form's field. */
  const propCol = propOn ? [["property", "Property"]] : [];
  const cols = completedMode
    ? [["client", "Client"], ...propCol, ["stage", "Status"], ["completed_at", "Completed"], ["lender", "Lender"], ["loan_amount", "Loan"], ["broker_fee", "Broker fee"], ["fee_status", "Fee status"], ["assigned", "Adviser"]]
    : [["client", "Client"], ...propCol, ["stage", "Stage"], ["days_in_stage", "In stage"], ["case_kind", "Type"], ["lender", "Lender"], ["rate_percent", "Rate"], ["rate_end_date", "Rate ends"], ["erc_end_date", "ERC ends"], ["broker_fee", "Fee"], ["fee_status", "Fee status"], ["protection_status", "Protection"], ["assigned", "Adviser"], ["updated_at", "Updated"]];
  let sk = sortKey, sd = sortDir;
  if (completedMode && !cols.some(([k]) => k === sortKey)) { sk = "completed_at"; sd = -1; }
  rows = rows.slice().sort((a, b) => {
    /* R6-FIX T4 — a case with no address is not "last alphabetically", it is ABSENT, and absence
       has no place at either end of a deliberate sort. Ascending already pushed the ~45 legacy
       NULL rows to the bottom with a sentinel; clicking the header again put every one of them at
       the TOP, so a quarter of the table was blank before the first real address. They stay last
       in both directions and the addressed rows reverse around them. */
    if (sk === "property") {
      const ax = !!propLabel(a), bx = !!propLabel(b);
      if (ax !== bx) return ax ? -1 : 1;
    }
    const x = val(a, sk), y = val(b, sk);
    return (x < y ? -1 : x > y ? 1 : 0) * sd;
  });

  // BUILD 7c — prune any bulk selection down to what's still visible in this filter/segment/tab, so
  // "select-all" and the action bar only ever act on the rows on screen.
  const rowIds = new Set(rows.map((c) => c.id));
  [...pipeSel].forEach((id) => { if (!rowIds.has(id)) pipeSel.delete(id); });
  const cbCell = (c) => `<td class="bulk-col" onclick="event.stopPropagation()"><input type="checkbox" class="bulk-cb" data-id="${c.id}" aria-label="Select this case"${pipeSel.has(c.id) ? " checked" : ""}></td>`;

  const bodyRows = completedMode
    ? rows.map((c) => `<tr onclick="openCase('${c.id}')" style="cursor:pointer;">
        ${cbCell(c)}
        <td class="stick-col"><strong>${esc([c.clients?.first_name, c.clients?.last_name].filter(Boolean).join(" "))}</strong></td>
        ${propOn ? `<td class="pipe-col-prop">${propChip(c) || '<span class="cs-muted">—</span>'}</td>` : ""}
        <td>${stageBadge(c.stage)}</td>
        <td>${c.completed_at ? fmtD(c.completed_at) : "—"}</td>
        <td>${lenderIcon(c.lender)}${esc(c.lender || "")}</td>
        <td>${c.loan_amount ? fmtM(c.loan_amount) : ""}</td>
        <td>${c.broker_fee ? fmtM(c.broker_fee) : ""}</td>
        <td>${esc((c.fee_status || "").replace(/_/g, " "))}</td>
        <td>${c.assigned_to ? esc(staffName(c.assigned_to)) : ""}</td>
      </tr>`).join("")
    : rows.map((c) => `<tr onclick="openCase('${c.id}')" style="cursor:pointer;">
        ${cbCell(c)}
        <td class="stick-col"><strong>${esc([c.clients?.first_name, c.clients?.last_name].filter(Boolean).join(" "))}</strong></td>
        ${propOn ? `<td class="pipe-col-prop">${propChip(c) || '<span class="cs-muted">—</span>'}</td>` : ""}
        ${/* R9-5 — the waiting-on chip rides in the Stage cell rather than taking a column of its
             own: the table is already fourteen columns wide on a live segment, and "who is it
             with" is a qualifier on the stage, not a separate axis. */ ""}
        <td>${stageBadge(c.stage)}${waitingChipHtml(c)}</td>
        <td>${(() => { const a = cardAge(c, stageEntry[c.id]); return a.inStage == null ? "" : `<span class="age-cell${a.level ? " age-" + a.level : ""}" title="${esc(a.basis)}">${a.inStage}d</span>`; })()}</td>
        <td>${esc((KINDS.find((x) => x[0] === c.case_kind) || [])[1] || "")}</td>
        <td>${lenderIcon(c.lender)}${esc(c.lender || "")}</td>
        <td>${c.rate_percent != null ? c.rate_percent + "%" : ""}</td>
        <td>${c.rate_end_date ? fmtD(c.rate_end_date) + (c.rate_end_estimated ? " " + APPROX : "") : ""}</td>
        <td>${c.erc_end_date ? fmtD(c.erc_end_date) : ""}</td>
        <td>${c.broker_fee ? fmtM(c.broker_fee) : ""}</td>
        <td>${esc((c.fee_status || "").replace(/_/g, " "))}</td>
        <td>${esc((c.protection_status || "").replace(/_/g, " "))}</td>
        <td>${c.assigned_to ? esc(staffName(c.assigned_to)) : ""}</td>
        <td class="pipe-col-updated">${fmtD(c.updated_at)}</td>
      </tr>`).join("");
  $("#table-wrap").innerHTML = `
    <div class="bulk-bar" id="pipe-bulk-bar"${pipeSel.size ? "" : " hidden"}>
      <span class="bulk-bar-count"><strong id="pipe-bulk-n">${pipeSel.size}</strong> selected</span>
      <select id="pipe-bulk-stage" class="bulk-bar-select" aria-label="Move selected cases to stage">
        <option value="" selected>Move to stage…</option>
        ${STAGES.map(([k, l]) => `<option value="${k}">${l}</option>`).join("")}
      </select>
      <select id="pipe-bulk-adviser" class="bulk-bar-select" aria-label="Assign selected cases to adviser">${adviserOptionsHtml("Assign to…")}</select>
      <button type="button" class="btn btn-sm" id="pipe-bulk-rate" title="Queue a rate-end reminder for every selected case that has a client email and a rate end date. Nothing is sent now.">⏰ Queue rate-end reminders</button>
      ${/* R7-2 — the bulk half of the retention sweep. A rate-end review is done a dozen rows at a
           time off this table, and the only route to it was one button on one row of one dashboard
           panel. It runs the SAME per-case flow, confirm by confirm, and tallies at the end. */ ""}
      <button type="button" class="btn btn-sm" id="pipe-bulk-retention" title="Start a retention case for every selected completed case whose rate is ending. Each one asks you to confirm, exactly as the single-case button does.">🔁 Start retention cases</button>
      <button type="button" class="btn btn-sm" id="pipe-bulk-task">＋ Add task…</button>
      <button type="button" class="btn btn-sm" id="pipe-bulk-clear">Clear</button>
    </div>
    <div class="board-scroll-wrap board-scroll-wrap--table">
    <div class="panel" id="pipe-scroll" style="overflow-x:auto;">
    <div style="display:flex;justify-content:flex-end;margin-bottom:8px;"><button class="btn btn-sm" id="csv-btn">⬇ Download CSV</button></div>
    ${rows.length ? `<table class="imp-table has-bulk" id="pipe-table">
      <tr><th class="bulk-col"><input type="checkbox" id="pipe-bulk-all" aria-label="Select all cases in this view"></th>${cols.map(([k, l]) => `<th data-k="${k}" class="${k === "client" ? "stick-col" : k === "updated_at" ? "pipe-col-updated" : ""}" style="cursor:pointer;"${k === "erc_end_date" ? ` title="${TIP_ERC}"` : ""}>${l}${sk === k ? (sd > 0 ? " ▲" : " ▼") : ""}</th>`).join("")}</tr>
      ${bodyRows}
    </table>` : `<div class="empty" style="padding:40px 16px;text-align:center;">No cases in this view.</div>`}</div>
    <button type="button" class="board-scroll-arrow" aria-label="Scroll right" title="Scroll right">›</button>
    </div>`;
  wireTableHScroll("pipe-scroll");
  document.querySelectorAll("#pipe-table th[data-k]").forEach((th) => (th.onclick = () => {
    const k = th.dataset.k;
    if (sortKey === k) sortDir *= -1; else { sortKey = k; sortDir = 1; }
    loadPipeline();
  }));
  // BUILD 7c — bulk-select wiring (checkboxes, select-all, action bar). No full reload on toggle —
  // the bar updates imperatively so scroll position and sort survive.
  document.querySelectorAll("#pipe-table .bulk-cb").forEach((cb) => (cb.onchange = () => {
    if (cb.checked) pipeSel.add(cb.dataset.id); else pipeSel.delete(cb.dataset.id);
    updatePipeBulkBar();
  }));
  const allCb = $("#pipe-bulk-all");
  if (allCb) allCb.onchange = () => {
    document.querySelectorAll("#pipe-table .bulk-cb").forEach((cb) => {
      cb.checked = allCb.checked;
      if (allCb.checked) pipeSel.add(cb.dataset.id); else pipeSel.delete(cb.dataset.id);
    });
    updatePipeBulkBar();
  };
  const clearBtn = $("#pipe-bulk-clear");
  if (clearBtn) clearBtn.onclick = () => {
    pipeSel.clear();
    document.querySelectorAll("#pipe-table .bulk-cb").forEach((cb) => (cb.checked = false));
    updatePipeBulkBar();
  };
  const stageSel = $("#pipe-bulk-stage");
  if (stageSel) stageSel.onchange = () => { const v = stageSel.value; stageSel.value = ""; if (v) bulkMoveStage(v); };
  const advSel = $("#pipe-bulk-adviser");
  if (advSel) advSel.onchange = () => { const v = advSel.value; advSel.value = ""; if (v) bulkAssignCases(v); };
  // S3a / S3b — the two bulk verbs a rate-end sweep actually needs.
  const rateBtn = $("#pipe-bulk-rate");
  if (rateBtn) rateBtn.onclick = () => bulkQueueRateReminders();
  const retBtn = $("#pipe-bulk-retention");
  if (retBtn) retBtn.onclick = () => bulkStartRetention();
  const taskBtn = $("#pipe-bulk-task");
  if (taskBtn) taskBtn.onclick = () => bulkAddTask();
  updatePipeBulkBar();
  $("#csv-btn").onclick = () => exportCsv(rows, completedMode, propOn);
}
// BUILD 7c — reflect the current pipeline selection into the action bar (visibility + count) and the
// select-all checkbox's checked/indeterminate state, without re-rendering the table.
function updatePipeBulkBar() {
  const bar = $("#pipe-bulk-bar");
  if (!bar) return;
  const n = pipeSel.size;
  bar.hidden = n === 0;
  const nEl = $("#pipe-bulk-n"); if (nEl) nEl.textContent = n;
  const all = $("#pipe-bulk-all");
  if (all) {
    const boxes = [...document.querySelectorAll("#pipe-table .bulk-cb")];
    const checked = boxes.filter((b) => b.checked).length;
    all.checked = checked > 0 && checked === boxes.length;
    all.indeterminate = checked > 0 && checked < boxes.length;
  }
}
function exportCsv(rows, completedMode = false, propOn = true) {
  const q2 = (v) => {
    let s = String(v ?? "");
    // Neutralise spreadsheet formula injection (=, +, -, @, tab, CR at start)
    if (/^[=+\-@\t\r]/.test(s)) s = "'" + s;
    return `"${s.replace(/"/g, '""')}"`;
  };
  /* A firm-wide spreadsheet of every colleague's broker fee is the same figure the Today tile and
     the Reports page withhold from a non-Owner, so the column is dropped here rather than exported
     one click later. Presentation only — nothing stops a signed-in adviser reading broker_fee from
     the API; the fee on an individual case is still on the case.
     R5-F1 (Daniel-approved) — but an adviser exporting THEIR OWN book was being denied their own
     money, which is the same reversal as the My numbers card. csvShowsFee() keeps the column when
     every row in this export is the signed-in adviser's own case and drops it the moment a
     colleague's row is in view, so the scope decides, not the click. Owner and admin unchanged. */
  const money = csvShowsFee(rows);
  /* R6 — the export carried twelve columns and no property, so a landlord's five cases left this
     app as five identical name rows. The FULL address goes in the file (a spreadsheet has room,
     and the short chip label is a screen affordance, not a record). */
  const head = (completedMode
    ? ["Client", "Property", "Status", "Completed", "Lender", "Loan", "Broker fee", "Fee status", "Adviser"]
    : ["Client", "Property", "Stage", "Type", "Lender", "Rate %", "Rate end", "Rate end estimated", "ERC end", "Broker fee", "Fee status", "Protection", "Adviser", "Updated"]
  ).filter((h) => (money || h !== "Broker fee") && (propOn || h !== "Property"));
  const row = (c) => (completedMode ? [
    [c.clients?.first_name, c.clients?.last_name].filter(Boolean).join(" "),
    propOn ? propAddress(c) || "" : null,
    STAGE_LABEL[c.stage] || c.stage, (c.completed_at || "").slice(0, 10), c.lender || "",
    c.loan_amount ?? "", money ? c.broker_fee ?? "" : null, c.fee_status || "", c.assigned_to ? staffName(c.assigned_to) : "",
  ] : [
    [c.clients?.first_name, c.clients?.last_name].filter(Boolean).join(" "),
    propOn ? propAddress(c) || "" : null,
    STAGE_LABEL[c.stage] || c.stage, (KINDS.find((x) => x[0] === c.case_kind) || [])[1] || c.case_kind, c.lender || "", c.rate_percent ?? "", c.rate_end_date || "",
    c.rate_end_estimated ? "yes" : "", c.erc_end_date || "", money ? c.broker_fee ?? "" : null,
    c.fee_status || "", c.protection_status || "", c.assigned_to ? staffName(c.assigned_to) : "",
    (c.updated_at || "").slice(0, 10),
  ]).filter((v) => v !== null);
  const lines = [head.map(q2).join(",")].concat(rows.map((c) => row(c).map(q2).join(",")));
  const blob = new Blob(["﻿" + lines.join("\n")], { type: "text/csv" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = `pipeline-${pipelineSegment}-${stageTab}-${new Date().toISOString().slice(0, 10)}.csv`;
  a.click();
}
$("#report-month").addEventListener("change", () => loadReports());
$("#view-toggle").addEventListener("click", () => {
  if (pipelineSegment === "completed") return; // locked to table in Completed
  pipelineView = pipelineView === "board" ? "table" : "board";
  if (authUid) lsSet(viewStoreKey(authUid), pipelineView);
  syncViewToggle();
  loadPipeline();
});
$("#board-search").addEventListener("input", debounce(() => loadPipeline(), 250));
$("#board-adviser").addEventListener("change", debounce(() => loadPipeline(), 250));
$("#new-case-btn").addEventListener("click", () => openCase(null));
// Board horizontal-scroll affordance wiring (QW16).
(() => {
  const board = $("#board");
  if (board) board.addEventListener("scroll", updateBoardScrollHint, { passive: true });
  const arrow = document.querySelector(".board-scroll-arrow");
  if (arrow) arrow.addEventListener("click", () => $("#board").scrollBy({ left: 320, behavior: "smooth" }));
  window.addEventListener("resize", updateBoardScrollHint);
})();

/* ---------- Protection & GI page ---------- */
let protScope = "mine", protFilter = "all";
const PROT_BADGE = {
  not_discussed: ["grey", "NOT DISCUSSED"], discussed: ["blue", "DISCUSSED"], quoted: ["amber", "QUOTED"],
  policy_taken: ["green", "POLICY TAKEN"], declined: ["red", "DECLINED"],
};
const GI_BADGE = {
  not_discussed: ["grey", "GI not discussed"], quoted: ["amber", "GI quoted"], policy_taken: ["green", "GI taken"],
  declined: ["red", "GI declined"], not_applicable: ["grey", "GI n/a"],
};
// The settable protection statuses, shared by the per-row select and S3c's bulk bar so the two can
// never drift apart. (not_discussed is deliberately absent — nothing moves a case backwards here.)
const PROT_BULK_STATUS = [["discussed", "Discussed"], ["quoted", "Quoted"], ["policy_taken", "Policy taken"], ["declined", "Declined"]];
/* ---------- R12a·D4 — THE CASE-HEADER PROTECTION CHIP, ALWAYS ----------
   It used to render ONLY for `not_discussed`, so the act of recording the conversation DELETED the
   indicator: the header went from "not discussed" to saying nothing at all, while Reports went on
   counting that same case under "No protection outcome" (see the Data-health item at ~8749 and the
   Protection call list's own basis line, "protection_status not policy_taken and not declined").
   Screen and report disagreed about the identical case — and the disagreement was in the direction
   that hides work, because "no chip" reads as "nothing to do here".

   So the chip is now unconditional and says which of the five states the case is actually in, in
   the report's own words. `discussed` is deliberately still AMBER: it is an open gap by every
   measure this app takes, and colouring it neutral would be the same lie in a quieter voice.
   `declined` is neutral rather than red — a client saying no is a finished conversation, not a
   problem. Only `policy_taken` is green.

   The id stays `cs-prot-warn` (the call-logger at ~8105 reaches for it by that id) — the element
   is now REPLACED rather than removed when the call logger records the conversation. */
function protStatChipHtml(c, stage) {
  const st = (c && c.protection_status) || "not_discussed";
  const quotedAt = c && c.protection_quoted_at;
  /* R15 · §6 — at OFFER/EXCHANGE a passive "not discussed / discussed" chip is a gap the adviser
     can close RIGHT NOW (the offer is out; protection is the last open thing), so the chip becomes
     an active prompt that reveals the protection field. Elsewhere it stays the plain status chip. */
  if (["offer", "exchange"].includes(stage) && ["not_discussed", "discussed"].includes(st)) {
    return `<div class="cs-stat cs-warn cs-prot-prompt" id="cs-prot-warn" data-prot="${esc(st)}" style="cursor:pointer;" title="Protection is the last open thing on a case at ${esc(STAGE_LABEL[stage] || stage)}. Click to record the conversation."><span class="cs-lbl">Protection</span><span class="cs-val">Discuss protection →</span></div>`;
  }
  const S = {
    not_discussed: ["cs-warn", "not discussed", "Nobody has recorded a protection conversation on this case. It counts as an open gap on Reports and Data health."],
    discussed: ["cs-warn", "discussed — no outcome yet", "The conversation happened but nothing came of it yet — no quote, no policy, no decline. Reports still count this case under “No protection outcome”."],
    quoted: ["cs-warn", quotedAt ? "quoted " + fmtD(quotedAt) : "quoted", quotedAt ? `Quoted ${fmtD(quotedAt)}. Still an open outcome until a policy is taken or the client declines.` : "Quoted, but no quote date is recorded — the “quotes gone cold” report cannot age this one."],
    policy_taken: ["cs-good", "policy taken", "A policy was taken. This is the only protection outcome that earns anything."],
    declined: ["", "declined", "The client was asked and said no. A finished conversation, not an open gap."],
  }[st] || ["cs-warn", String(st).replace(/_/g, " "), ""];
  return `<div class="cs-stat ${S[0]}" id="cs-prot-warn" data-prot="${esc(st)}" title="${esc(S[2])}"><span class="cs-lbl">Protection</span><span class="cs-val">${esc(S[1])}</span></div>`;
}
async function loadProtectionPage() {
  // T1-5: the RPC's "mine" scope also hands back every ownerless case, so "Mine" meant "mine plus
  // nobody's" for all three advisers at once. Fetch the whole book and apply the scope here, where
  // Mine / Unassigned / All are three distinct, honest sets.
  const { data, error } = await db.rpc("get_protection_pipeline", { p_scope: "all" });
  if (error) {
    $("#prot-table").innerHTML = `<div class="empty">Protection pipeline unavailable — ${esc(error.message)}</div>`;
    return;
  }
  /* R7-3 — the scope filter is split out from the status filter, because the "completed, no
     protection outcome" call list below answers to the SCOPE (whose book am I looking at) but not
     to the drop-down (which slice of it) — a call list that disappeared when you filtered to
     "Live cases" would be a call list nobody ever worked. */
  const scoped = (Array.isArray(data) ? data : []).filter((r) => {
    if (protScope === "mine" && r.owner !== (ME && ME.id)) return false;
    if (protScope === "unassigned" && r.owner != null) return false;
    return true;
  });
  const rows = scoped.filter((r) => {
    if (protFilter === "live") return r.live;
    if (protFilter === "completed") return !r.live;
    if (protFilter === "quoted") return r.protection_status === "quoted";
    return true;
  });
  const estTotal = rows.reduce((s, r) => s + Number(r.est_commission || 0), 0);
  /* BACKEND-R4 §1 (owner's decision) — commission is money reporting, and money reporting is
     Owner-only IN THE UI. This page was the one that never asked: the RPC is called with scope
     "all", so "Est. commission" is the WHOLE firm's estimated protection commission and reads the
     same for an adviser as for the Owner, and the Est. £ column is that same money case by case.
     Same gate as Today and Reports, and the same caveat: THIS IS PRESENTATION, NOT A SECURITY
     CONTROL. get_protection_pipeline() still returns est_commission to any staff session and the
     cases table still carries protection_commission — anyone with the browser console can read
     what this hides. Opportunity counts, statuses and who each case sits with are unaffected. */
  const money = showMoney();
  const commTile = $("#prot-kpi-comm") ? $("#prot-kpi-comm").closest(".kpi") : null;
  if (commTile) commTile.classList.toggle("hidden", !money);
  const protNote = $("#prot-money-note");
  if (protNote) {
    protNote.classList.toggle("hidden", money);
    protNote.textContent = money ? "" : "Estimated commission is shown to the Owner only — the figure on this page is the whole firm's, not yours. Opportunity counts, protection and GI status and the adviser each case sits with are all below, and the commission on an individual case is on the case itself.";
  }
  $("#prot-kpi-count").textContent = rows.length;
  $("#prot-kpi-comm").textContent = money ? fmtM(estTotal) : "—";
  $("#prot-kpi-quoted").textContent = rows.filter((r) => r.protection_status === "quoted").length;
  /* S3c — bulk-select on this table. Same pattern as the pipeline's (BUILD 7c): the selection is
     pruned to what is actually on screen after every filter/scope change, so "6 selected" can only
     ever mean six rows the operator can see. */
  const protRowIds = new Set(rows.map((r) => r.case_id));
  [...protBulkSel].forEach((id) => { if (!protRowIds.has(id)) protBulkSel.delete(id); });
  const protCb = (r) => `<td class="bulk-col"><input type="checkbox" class="prot-cb bulk-cb" data-id="${r.case_id}" aria-label="Select this case"${protBulkSel.has(r.case_id) ? " checked" : ""}></td>`;
  /* R6-FIX OP-02/V1 — the CASE column was the round-5 "stage + kind · lender" string, i.e. exactly
     the label this round exists to replace, on the one nav-level page whose row actions (Task,
     Email) start a conversation with the client. Gareth Pollard holds three rows here, one of them
     with no lender at all ("Enquiry Buy to Let"), which named none of his five buildings. Same
     chip, same rules, same batched lookup as Today's lists — the RPC carries no property column,
     so the cases behind the rows on screen are resolved in one read. */
  const protPageCtx = await loadPropContext(rows.map((r) => r.case_id));
  /* R7-3 — the quote clock. get_protection_pipeline carries the status but not when it was set, so
     the stamps for the quoted rows on screen are read in one batched query; on a database without
     M8 the map comes back empty and every badge reads "quote age unknown" rather than throwing. */
  const protQuoteCtx = await loadQuoteStamps(scoped.filter((r) => r.protection_status === "quoted").map((r) => r.case_id));
  $("#prot-table").innerHTML = rows.length ? `
    <div class="bulk-bar" id="prot-bulk-bar"${protBulkSel.size ? "" : " hidden"}>
      <span class="bulk-bar-count"><strong id="prot-bulk-n">${protBulkSel.size}</strong> selected</span>
      <select id="prot-bulk-status" class="bulk-bar-select" aria-label="Set protection status on selected cases">
        <option value="" selected>Set status →</option>
        ${PROT_BULK_STATUS.map(([k, l]) => `<option value="${k}">${l}</option>`).join("")}
      </select>
      <button type="button" class="btn btn-sm" id="prot-bulk-clear">Clear</button>
    </div>
    <div class="board-scroll-wrap board-scroll-wrap--table">
    <div class="panel prot-table-wrap" id="prot-scroll">
    <table class="imp-table has-bulk" id="prot-list-table">
      <tr><th class="bulk-col"><input type="checkbox" id="prot-bulk-all" aria-label="Select all cases in this view"></th><th class="prot-col-n">#</th><th class="stick-col">Client</th><th>Case</th><th class="prot-col-loan">Loan</th><th>Status</th>${money ? '<th class="prot-col-est">Est. £</th>' : ""}<th>Adviser</th><th class="stick-col-right">Actions</th></tr>
      ${rows.map((r, i) => {
        const kind = (KINDS.find((x) => x[0] === r.case_kind) || [])[1] || "";
        const p = PROT_BADGE[r.protection_status] || PROT_BADGE.not_discussed;
        const gi = caseGiApplies(r.case_kind) ? (GI_BADGE[r.gi_status] || GI_BADGE.not_discussed) : null;
        return `<tr>
        ${protCb(r)}
        <td class="prot-col-n" style="color:var(--muted);">${i + 1}</td>
        <td class="stick-col"><span class="prot-client" onclick="openClient('${r.client_id}')">${esc(r.client_name)}</span><span class="prot-fold-info">Loan ${fmtM(r.loan_amount)}${money ? " · Est. " + fmtM(r.est_commission) : ""}</span></td>
        <td class="prot-col-case">${(() => {
          const chip = propCtxChip(protPageCtx, r.case_id, "row-prop", { noStage: true });
          return `${stageBadge(r.stage)} ${esc(kind)}${r.lender ? " · " : " "}${lenderIcon(r.lender)}${esc(r.lender || "")}${chip ? `<div class="prot-case-prop">${chip}</div>` : ""}`;
        })()}</td>
        <td class="prot-col-loan">${fmtM(r.loan_amount)}</td>
        <td><span class="badge ${p[0]}">${p[1]}</span>${r.protection_status === "quoted" ? " " + quoteAgeBadge((protQuoteCtx[r.case_id] || {}).protection_quoted_at) : ""}${gi ? ` <span class="badge ${gi[0]}" title="${TIP_GI}">${gi[1]}</span>` : ""}</td>
        ${money ? `<td class="prot-est prot-col-est">${fmtM(r.est_commission)}</td>` : ""}
        ${/* R6-FIX V14 — a case owned by a staff id that is not on the roster (a leaver) produced
              initials(""), i.e. an avatar with no letters in it: a solid navy circle, which now
              reads as a colour dot in an app where colour dots mean a property. Say what it is. */ ""}
        <td>${!r.owner ? '<span class="cs-muted">— unassigned —</span>'
          : initials(r.owner) ? `<span class="chip" title="${esc(staffName(r.owner))}">${esc(initials(r.owner))}</span>`
          : `<span class="cs-muted" title="This case is assigned to a staff id that is not on the current roster (${esc(r.owner)}) — most likely someone who has left. Reassign it from the case.">— off roster —</span>`}</td>
        <td class="stick-col-right prot-actions">
          <button class="btn btn-sm" onclick="openCase('${r.case_id}')">Open</button>
          ${/* R6-B4 (W21) — the placeholder is shortened from "Set status…"/"Set GI…" to
               "Status…"/"GI…" and each select is sized to THAT rather than to its longest
               option. Before, the pair were 132px each and still ellipsised — "Set GI…"
               told you nothing — and together with three buttons they made this cell
               429px wide, wider than a phone. The current value is not lost: it is the
               badge in the STATUS column of the same row, which is now never covered. */ ""}
          <select class="prot-status-set" onchange="setProtStatus('${r.case_id}', this.value)" title="Set protection status" aria-label="Set protection status">
            <option value="">Status…</option>
            ${PROT_BULK_STATUS.map(([k, l]) => `<option value="${k}">${l}</option>`).join("")}
          </select>
          ${gi ? `<select class="prot-status-set prot-gi-set" onchange="setGiStatus('${r.case_id}', this.value)" title="Set general-insurance status" aria-label="Set general-insurance status">
            <option value="">GI…</option>
            ${[["quoted", "GI quoted"], ["policy_taken", "GI taken"], ["declined", "GI declined"], ["not_applicable", "GI n/a"]].map(([k, l]) => `<option value="${k}">${l}</option>`).join("")}
          </select>` : ""}
          <button class="btn btn-sm" onclick="protCallTask('${r.case_id}')">Task</button>
          ${r.has_email ? `<button class="btn btn-sm" onclick="protQueueEmail('${r.case_id}', event)">Email</button>` : '<span class="badge grey">no email</span>'}
        </td>
      </tr>`;
      }).join("")}
    </table>
    </div>
    <button type="button" class="board-scroll-arrow" aria-label="Scroll right" title="Scroll right">›</button>
  </div>` : '<div class="empty">No protection or GI opportunities in this view — nice clean book. 🛡️</div>';
  wireTableHScroll("prot-scroll");
  // S3c — bulk wiring. The bar updates imperatively (no re-render) so a long selection survives.
  document.querySelectorAll("#prot-list-table .prot-cb").forEach((cb) => (cb.onchange = () => {
    if (cb.checked) protBulkSel.add(cb.dataset.id); else protBulkSel.delete(cb.dataset.id);
    updateProtBulkBar();
  }));
  const protAll = $("#prot-bulk-all");
  if (protAll) protAll.onchange = () => {
    document.querySelectorAll("#prot-list-table .prot-cb").forEach((cb) => {
      cb.checked = protAll.checked;
      if (protAll.checked) protBulkSel.add(cb.dataset.id); else protBulkSel.delete(cb.dataset.id);
    });
    updateProtBulkBar();
  };
  const protClear = $("#prot-bulk-clear");
  if (protClear) protClear.onclick = () => {
    protBulkSel.clear();
    document.querySelectorAll("#prot-list-table .prot-cb").forEach((cb) => (cb.checked = false));
    updateProtBulkBar();
  };
  const protStatusSel = $("#prot-bulk-status");
  if (protStatusSel) protStatusSel.onchange = () => { const v = protStatusSel.value; protStatusSel.value = ""; if (v) bulkSetProtStatus(v); };
  updateProtBulkBar();
  renderProtCallList(scoped, protQuoteCtx);
  renderClawbackWindow();
}
/* ---------- R13 · M-23/M-25 — THE CLAWBACK WINDOW ----------
   get_protection_pipeline deliberately returns only the OPEN protection statuses, so this panel
   cannot be built from `scoped` — a policy that was taken is exactly what it left out. One extra
   read of the cases whose protection status is policy_taken, feature-detected on the column and
   silent (panel hidden) without it.

   NOT scoped by the Mine / Unassigned / All buttons above, and that is deliberate: a clawback is
   money the FIRM pays back. Whose case it was does not change who is out of pocket, and an adviser
   filtering to "Mine" and seeing an empty clawback list would be reading a true statement about
   their book as a false one about the risk. The adviser IS named on every row. */
async function renderClawbackWindow() {
  const panel = $("#prot-clawback-panel");
  if (!panel) return;
  if ((await policyStartSupported()) === false) { panel.classList.add("hidden"); return; }
  const { data, error } = await db.from("cases")
    .select("id,client_id,policy_start_date,protection_commission,assigned_to,clients!client_id(first_name,last_name)")
    .eq("protection_status", "policy_taken");
  if (error) {
    if (isMissingColumnError(error)) { POLICY_START_SUPPORTED = false; panel.classList.add("hidden"); return; }
    panel.classList.remove("hidden");
    $("#prot-clawback-list").innerHTML = `<div class="empty">Clawback window unavailable just now — ${esc(error.message)}</div>`;
    return;
  }
  const rows = Array.isArray(data) ? data : [];
  if (rows.length) notePolicyStartFromStarRow(rows[0]);
  panel.classList.remove("hidden");
  const money = showMoney();
  const noDate = rows.filter((r) => !r.policy_start_date);
  const inWindow = rows
    .map((r) => ({ ...r, months: clawbackMonthsElapsed(r.policy_start_date) }))
    .filter((r) => r.months != null && r.months >= 0 && r.months < CLAWBACK_MONTHS)
    .sort((a, b) => (b.months - a.months) || 0);   // closest to falling out of the window first
  const nameOf = (r) => [r.clients && r.clients.first_name, r.clients && r.clients.last_name].filter(Boolean).join(" ") || "(client not on file)";
  const countEl = $("#prot-clawback-count");
  countEl.textContent = inWindow.length;
  countEl.className = "badge " + (inWindow.length ? "amber" : "grey");
  $("#prot-clawback-basis").innerHTML = `Policies recorded as taken whose start date falls inside the last <strong>${CLAWBACK_MONTHS} months</strong> — the period in which a provider would typically reclaim the commission if the policy lapses. `
    + `<strong>${CLAWBACK_MONTHS} months is an assumption</strong>, not a figure read from anywhere: providers differ, and this app holds no per-provider clawback terms. Check the provider's own schedule before you rely on a number here.`
    + (money ? "" : ` Commission is shown to the Owner only; the count and the dates are not money and are shown to everyone.`);
  /* THE HONEST HALF, and the reason the panel exists at all. A policy with no start date is not a
     policy outside the window — it is a policy whose window nobody can see. Said as a count with
     the fix attached, because the fix is one date on one case. */
  $("#prot-clawback-nodate").innerHTML = noDate.length
    ? `<strong id="prot-clawback-nodate-n">${noDate.length} polic${noDate.length === 1 ? "y has" : "ies have"} no start date recorded</strong> — their clawback window cannot be watched. Add the date on the case (Protection section of the case form). They are listed below the table.`
    : rows.length ? `Every policy taken has a start date recorded. 👍` : "";
  const rowHtml = (r) => `<tr data-case="${esc(r.id)}">
      <td><span class="prot-client" onclick="openCase('${jsArg(r.id)}')">${esc(nameOf(r))}</span></td>
      <td>${fmtD(r.policy_start_date)}</td>
      <td class="clawback-months">${r.months} of ${CLAWBACK_MONTHS}</td>
      <td class="clawback-months${CLAWBACK_MONTHS - r.months <= 3 ? " clawback-left-hot" : ""}">${CLAWBACK_MONTHS - r.months}</td>
      ${money ? `<td>${r.protection_commission > 0 ? fmtM(r.protection_commission) : '<span class="cs-muted">none recorded</span>'}</td>` : ""}
      <td>${r.assigned_to ? esc(staffName(r.assigned_to)) : '<span class="cs-muted">— unassigned —</span>'}</td>
      <td style="text-align:right;"><button class="btn btn-sm" onclick="openCase('${jsArg(r.id)}')">Open</button></td>
    </tr>`;
  $("#prot-clawback-list").innerHTML = (inWindow.length ? `<table class="imp-table" id="prot-clawback-table">
      <tr><th>Client</th><th>Policy started</th><th>Months elapsed</th><th>Months left in window</th>${money ? "<th>Commission</th>" : ""}<th>Adviser</th><th></th></tr>
      ${inWindow.map(rowHtml).join("")}
    </table>` : `<div class="empty">No policy started in the last ${CLAWBACK_MONTHS} months${rows.length ? " — nothing is inside a clawback window" : ""}. 👍</div>`)
    + (noDate.length ? `<div class="dq-notice" id="prot-clawback-nodate-list" style="margin-top:12px;">
      <strong>No start date — window cannot be watched:</strong>
      ${noDate.map((r) => `<button type="button" class="btn btn-sm" onclick="openCase('${jsArg(r.id)}')">${esc(nameOf(r))}</button>`).join(" ")}
    </div>` : "");
}
/* ---------- R7-3 — "completed, no protection outcome" ----------
   The cases that got all the way to completion with the protection conversation left open: status
   still not_discussed, discussed or quoted, i.e. anything that is neither a policy nor a client
   who said no. Those are the calls worth making — the client has just moved house or remortgaged,
   the relationship is warm, and nobody has closed the loop.

   Scope follows the Mine / Unassigned / All buttons above, so an adviser reads their own list and
   the Owner reads the firm's. The rows themselves are counts and statuses, not money, so this
   panel is NOT Owner-gated: it is a work list, and withholding an adviser's own follow-up calls
   would be the opposite of the point. */
function renderProtCallList(scoped, quoteCtx) {
  const panel = $("#prot-calllist-panel");
  if (!panel) return;
  /* get_protection_pipeline already excludes not_proceeding and already returns ONLY the three
     open statuses, so within its output `!live` is exactly "completed, still open". */
  const list = (scoped || []).filter((r) => !r.live);
  panel.classList.remove("hidden");
  const scopeWord = protScope === "mine" ? "your cases" : protScope === "unassigned" ? "unassigned cases" : "every adviser's cases";
  const byStatus = { not_discussed: 0, discussed: 0, quoted: 0 };
  list.forEach((r) => { if (byStatus[r.protection_status] != null) byStatus[r.protection_status]++; });
  $("#prot-calllist-count").textContent = list.length;
  $("#prot-calllist-count").className = "badge " + (list.length ? "amber" : "green");
  $("#prot-calllist-basis").innerHTML =
    `Completed cases whose protection conversation is still open — ${byStatus.not_discussed} never discussed, ${byStatus.discussed} discussed, ${byStatus.quoted} quoted and waiting. `
    + `A client who has just completed is the warmest call the firm has. Scoped to <strong>${esc(scopeWord)}</strong> (the buttons above); the status drop-down does not narrow this list. `
    + `<span class="money-basis">(completed · protection_status not policy_taken and not declined)</span>`;
  $("#prot-calllist").innerHTML = list.length ? list.slice(0, 25).map((r) => {
    const p = PROT_BADGE[r.protection_status] || PROT_BADGE.not_discussed;
    return `<div class="row-item">
      <div class="row-main">
        <div class="t" onclick="openCase('${r.case_id}')">${esc(r.client_name)}</div>
        <div class="s">${stageBadge(r.stage)} ${lenderIcon(r.lender)}${esc(r.lender || "")} · loan ${fmtM(r.loan_amount)}${r.owner ? " · " + esc(staffName(r.owner)) : " · unassigned"}</div>
      </div>
      <span class="badge ${p[0]}">${p[1]}</span>
      ${r.protection_status === "quoted" ? quoteAgeBadge(((quoteCtx || {})[r.case_id] || {}).protection_quoted_at) : ""}
      <button class="btn btn-sm" onclick="protCallTask('${r.case_id}')">Task</button>
      ${r.has_email ? `<button class="btn btn-sm" onclick="protQueueEmail('${r.case_id}', event)">Email</button>` : '<span class="badge grey">no email</span>'}
    </div>`;
  }).join("") + (list.length > 25 ? `<div class="empty">…and ${list.length - 25} more — filter to "Completed book" above to work the whole list.</div>` : "")
    : '<div class="empty">Every completed case in this scope has a protection outcome recorded — a policy or a decline. Nothing to chase. 🛡️</div>';
}
// S3c — mirror the current protection selection into its action bar (count + select-all state).
function updateProtBulkBar() {
  const bar = $("#prot-bulk-bar");
  if (!bar) return;
  const n = protBulkSel.size;
  bar.hidden = n === 0;
  const nEl = $("#prot-bulk-n"); if (nEl) nEl.textContent = n;
  const all = $("#prot-bulk-all");
  if (all) {
    const boxes = [...document.querySelectorAll("#prot-list-table .prot-cb")];
    const checked = boxes.filter((b) => b.checked).length;
    all.checked = checked > 0 && checked === boxes.length;
    all.indeterminate = checked > 0 && checked < boxes.length;
  }
}
/* S3c — set one protection status across the selection. Deliberately NOT setProtStatus in a loop:
   six sequential prompts (plus six full page reloads) is not a bulk action.
   R7-3 — but "the commission is left for the case" is exactly the hole the single-case flow just
   closed, and leaving it open here would make the bulk bar the way round the rule. The figure is
   asked for ONCE and applied to every selected case, with the confirm saying so in as many words
   so nobody applies one policy's value to six by accident. Quoted stamps the quote clock on all of
   them, the same way and with the same M8 fallback. */
async function bulkSetProtStatus(status) {
  const ids = [...protBulkSel];
  if (!ids.length || !status) return;
  const label = (PROT_BULK_STATUS.find(([k]) => k === status) || [null, status])[1];
  let commission = null;
  if (status === "policy_taken") {
    commission = askProtectionCommission(null, `This figure will be written to ALL ${ids.length} selected case${ids.length === 1 ? "" : "s"} — if their policies are worth different amounts, cancel and set them one at a time.`);
    if (commission == null) return toast("Left unchanged — a policy needs a commission figure.");
  }
  const msg = `Set protection status to "${label}" on ${ids.length} case${ids.length === 1 ? "" : "s"}?`
    + (status === "policy_taken" ? `\n\nCommission ${fmtM(commission)} will be recorded on every one of them.` : "")
    /* R12a·D9 — this used to promise "the quote clock starts today on every one of them", and
       that is exactly the sweep that used to reset a cold quote to fresh. It now says what
       protUpdateWithStamp actually does. */
    + (status === "quoted" ? "\n\nThe quote clock starts today on any that are not already quoted. A quote date already on a case is left alone, so its age keeps counting." : "");
  if (!confirm(msg)) return;
  let ok = 0, err = 0, keptDates = 0;
  for (const id of ids) {
    const patch = { protection_status: status };
    if (commission != null) patch.protection_commission = commission;
    const { error, kept } = await protUpdateWithStamp(id, patch, status === "quoted");
    if (error) err++; else { ok++; if (kept) keptDates++; }
  }
  let out = `${ok} case${ok === 1 ? "" : "s"} set to ${label.toLowerCase()}`;
  if (commission != null) out += ` · commission ${fmtM(commission)} each`;
  if (keptDates) out += ` · ${keptDates} kept the quote date already on file`;
  if (err) out += ` · ${err} error${err === 1 ? "" : "s"}`;
  toast(out);
  protBulkSel.clear();
  loadProtectionPage();
}
/* ---------- R7-3 — the protection quote clock ----------
   Two writes that used to lose the two facts the protection book is judged on.

   1. QUOTED WITH NO DATE. "Quoted" was a label with no clock behind it, so a quote sent in March
      and a quote sent yesterday were the same amber pill and nothing anywhere could tell you which
      conversation had gone cold. Setting the status to quoted now stamps WHEN and BY WHOM, in the
      same write, so the badge on the row is derived rather than remembered.

   2. A POLICY WITH NO MONEY ON IT. The old prompt said "leave blank to skip" and most of them were
      skipped, so "policy taken" — the only outcome that earns anything — routinely carried no
      commission at all and the attach-rate figures below had nothing to weigh. The figure is now
      required. It is pre-filled with what the case already holds, or failing that with the firm's
      average from Settings, so the common case is one keystroke; Cancel abandons the change
      entirely rather than writing a policy with no value, and the reason is said out loud.

   Both columns behind (1) are M8. Feature-detected by absence, exactly as M1/M2/M7 are: on a
   database that has not taken the migration the stamp is dropped and the status change still
   lands, because refusing an adviser's status change over a reporting column would be absurd. */
const PROT_STAMP_COLS = ["protection_quoted_at", "protection_quoted_by"];
function protQuotedStamp() {
  return { protection_quoted_at: new Date().toISOString(), protection_quoted_by: (ME && ME.id) || null };
}
/* R12a·D9 — AND THE CLOCK MAY NEVER BE WOUND BACKWARDS.
   R7-3 above started the clock but stamped it on EVERY write that set the status to quoted, and
   the two entry points that go through here (the Protection page's per-row select and S3c's bulk
   bar) do not know what the status was before. So re-applying "Quoted" to a case that was already
   quoted — one bulk-bar sweep over a filtered "quoted" list is enough — moved
   protection_quoted_at to today, and a three-week-old quote that the "quotes gone cold" report
   exists to surface came back reading "0d · fresh". A report that can be silently reset by an
   unrelated click is worse than no report.

   The rule, decided once, here, so both callers and the case form agree:

     • CHANGING to quoted from anything else  → stamp. The quote was sent now.
     • ALREADY quoted, and no date on record  → stamp. This is the only route by which the twelve
       legacy rows carrying "quote age unknown" can ever acquire a date, and re-picking a value a
       <select> is already showing is a deliberate act (a same-value pick fires no change event at
       all, so this can only arrive from the bulk bar or the My Day "Mark quoted" button — both of
       which mean "I have just quoted this").
     • ALREADY quoted, date already on record → LEAVE IT. Never overwritten, never cleared.

   The pre-read is one narrow select on the row about to be written; it is skipped entirely unless
   a stamp is actually in play. If it fails we fall back to stamping, which is R7-3's behaviour and
   the safe end of the trade: the following update is about to fail for the same reason anyway.

   Returns {error, stamped, kept} — `kept` distinguishes "left the existing quote date alone" from
   `stamped:false`'s "this database has no column to stamp", so the toast can tell the truth about
   which of the two just happened. */
async function protQuoteStampDecision(caseId) {
  const { data, error } = await db.from("cases").select("protection_status,protection_quoted_at").eq("id", caseId).maybeSingle();
  if (error || !data) return { stamp: true, kept: false };
  if ((data.protection_status || "not_discussed") !== "quoted") return { stamp: true, kept: false };
  return data.protection_quoted_at ? { stamp: false, kept: true } : { stamp: true, kept: false };
}
async function protUpdateWithStamp(caseId, patch, wantStamp) {
  let stamped = !!wantStamp && (await protQuoteSupported());
  let kept = false;
  if (stamped) {
    const d = await protQuoteStampDecision(caseId);
    stamped = d.stamp; kept = d.kept;
  }
  const full = stamped ? Object.assign({}, patch, protQuotedStamp()) : patch;
  let { error } = await db.from("cases").update(full).eq("id", caseId);
  if (error && stamped && isMissingColumnError(error)) {
    stamped = false; PROT_QUOTE_SUPPORTED = false;
    ({ error } = await db.from("cases").update(patch).eq("id", caseId));
  }
  return { error: error || null, stamped, kept };
}
/* The required-commission capture. Returns a number, or null when the operator cancelled — and
   null MUST abort the status change, which is the whole point of it being required. */
function askProtectionCommission(existing, contextLine) {
  const avg = Number(settings.protection_avg_commission || 0);
  let def = Number(existing || 0) > 0 ? String(Number(existing)) : (avg > 0 ? String(avg) : "");
  /* Bounded, deliberately. "Required" must not mean "a modal you cannot leave except by Cancel":
     three goes is plenty for a typo, and the fourth abandons the change and says why, which is the
     same outcome as Cancel and never a policy written with no value on it. */
  for (let tries = 0; tries < 3; tries++) {
    const raw = prompt(
      "Policy taken 🎉 — what is the commission worth?\n\n"
      + (contextLine ? contextLine + "\n\n" : "")
      + "A figure is required: \"policy taken\" is the only protection outcome that earns anything, and "
      + "the attach-rate and commission figures on Reports are built from it. "
      + (avg > 0 ? `The box is pre-filled with the firm average from Settings (${fmtM(avg)}) — change it to the real figure if you know it.` : "")
      + "\n\nCancel leaves the status exactly as it is.",
      def);
    if (raw == null) return null;                       // cancelled — caller must abandon
    const v = String(raw).trim().replace(/^£/, "").replace(/,/g, "");
    if (v !== "" && !isNaN(Number(v)) && Number(v) > 0) return Number(v);
    def = v;
    toast(v === "" ? "A commission figure is required — enter one, or press Cancel to leave the status alone." : "That isn't a number above zero — try again, or press Cancel.");
  }
  return null;   // three goes, no usable figure — treated exactly as Cancel
}
window.setProtStatus = async function (caseId, status) {
  if (!status) return;
  const patch = { protection_status: status };
  if (status === "policy_taken") {
    const { data: cur } = await db.from("cases").select("protection_commission").eq("id", caseId).single();
    const amt = askProtectionCommission(cur && cur.protection_commission, null);
    if (amt == null) { loadProtectionPage(); return toast("Left unchanged — a policy needs a commission figure."); }
    patch.protection_commission = amt;
  }
  const { error, stamped, kept } = await protUpdateWithStamp(caseId, patch, status === "quoted");
  if (error) return toast("Error: " + error.message);
  toast(status === "quoted"
    /* R12a·D9 — three outcomes, three sentences. "kept" is the one that used to be a silent lie:
       the clock was reset and the toast congratulated the adviser on starting it. */
    ? (kept
      ? "Protection status: quoted — the quote date already on this case was left as it is, so its age keeps counting"
      : stamped
        ? "Protection status: quoted — quote clock started today"
        : "Protection status: quoted — but this database has no quote-date column (migration M8), so the age badge will read \u201cunknown\u201d")
    : status === "policy_taken"
      ? `Policy taken ✓ — commission ${fmtM(patch.protection_commission)} recorded`
      : "Protection status: " + status.replace(/_/g, " "));
  if (!$("#page-protection").classList.contains("hidden")) loadProtectionPage();
};
window.setGiStatus = async function (caseId, status) {
  if (!status) return;
  const { error } = await db.from("cases").update({ gi_status: status }).eq("id", caseId);
  if (error) return toast("Error: " + error.message);
  toast("GI status: " + status.replace(/_/g, " "));
  if (!$("#page-protection").classList.contains("hidden")) loadProtectionPage();
};
window.protCallTask = async function (caseId) {
  const { data: c } = await db.from("cases").select("assigned_to").eq("id", caseId).single();
  const due = localDateStr(Date.now() + 86400000);
  const { error } = await db.from("case_tasks").insert({
    case_id: caseId, title: "Protection call", due_date: due,
    created_by: (ME && ME.id) || null, assigned_to: (c && c.assigned_to) || (ME && ME.id) || null,
  });
  if (error) return toast("Error: " + error.message);
  toast("Protection call task added for tomorrow");
};
// T1-15 — takes `ev` explicitly (matching queueEmail/briefQueueEmail). The old version read the
// deprecated global `event`, so the double-click guard silently did nothing outside sloppy mode.
window.protQueueEmail = async function (caseId, ev) {
  const btn = (ev && (ev.currentTarget || ev.target)) || null;
  if (btn) { if (btn.disabled) return; btn.disabled = true; } // guard against double-click double-insert
  try {
    const { data: c } = await db.from("cases").select("*").eq("id", caseId).single();
    if (!c) return toast("Could not load case");
    const { data: cl } = await db.from("clients").select("email").eq("id", c.client_id).single();
    if (!cl?.email) return toast("This client has no email address — add one first.");
    if (!confirm("Queue the protection intro email? Ensure the template has principal approval.")) return;
    const { data: qRow, error } = await db.from("email_queue")
      .insert({ case_id: caseId, client_id: c.client_id, email_type: "protection_offer", to_email: cl.email })
      .select("id").single();
    if (error) return toast("Error: " + error.message);
    // R5-1 — scoped to the row just inserted; this button can no longer flush the firm's queue.
    const res = qRow && qRow.id ? await runAutomation(true, { queueIds: [qRow.id] }) : null;
    sendResultToast(res, "Email queued — check Emails tab");
  } finally {
    if (btn) btn.disabled = false;
  }
};
// Client link token for a fact-find. Generated here so a brand-new fact-find always carries a
// usable token (defect #3: without this the copyable link renders "token=undefined" wherever the
// DB doesn't back-fill the column). An explicit value is harmless where a DB default also exists.
function ffToken() {
  return (typeof crypto !== "undefined" && crypto.randomUUID)
    ? crypto.randomUUID()
    : "ff-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 10);
}
/* ---------- R12a·D3 — THE FACT-FIND SEND PATH ----------
   Three lies lived in this dialog, all of them about the same thing: whether anything was sent.

   1. OPENING IT MARKED THE FACT-FIND "SENT". The insert relied on the column default, which is
      'sent', so merely LOOKING at the dialog wrote a row claiming the client had been emailed a
      link. Nothing had been. The row is now inserted with an explicit status:'created' — the
      status the client link genuinely has the moment it is minted — and the badge for it says
      "not sent yet" in words, not a status enum.
   2. THE ONLY SEND WAS A mailto:. It opened the operator's mail client and recorded NOTHING —
      no email_queue row, no case note, no task, nothing on the Emails page. If the operator then
      closed the draft, the case still said "sent".
   3. THE mailto WAS SIGNED BY THE OWNER. It used settings.adviser_name, the firm-wide default,
      so Wayne emailing his own client signed off as Daniel and gave Daniel's contact details.
      queueEmail has had the right rule since ADV-1 (the CASE's adviser, falling back to the
      sender, and only then to the firm) — the mailto never got it.

   The primary control is now a real queued send: email_type "factfind", through the same
   queueEmail + scoped runAutomation machinery the docs_request "send now" button uses, which
   process-emails v12 composes server-side (it resolves this same fact_finds row, builds the link
   from site_url, and advances the row to 'sent' only AFTER the send succeeds). The mailto stays
   as an explicit second choice for the adviser who wants to write it themselves — signed off
   correctly now, and leaving a case note that says exactly what the system does and does not
   know about it. */
const FF_BADGE = {
  created:   ["badge grey",  "not sent yet", "The link exists but nothing has gone to the client yet."],
  sent:      ["badge blue",  "sent",         "The link was emailed to the client. If no date is shown beside this, the send predates the queued fact-find email and no date was recorded for it."],
  started:   ["badge amber", "started",      "The client has opened the form and begun filling it in."],
  submitted: ["badge green", "submitted",    "The client has finished and sent their answers back."],
};
window.factFind = async function (caseId, clientId) {
  /* The case row is read here for one reason: the sign-off. Both send routes have to name the
     CASE's adviser, and neither of them had the case to hand before. */
  const { data: kase } = await db.from("cases").select("*").eq("id", caseId).single();
  let { data: ff } = await db.from("fact_finds").select("*").eq("case_id", caseId).order("created_at", { ascending: false }).limit(1).maybeSingle();
  if (!ff) {
    /* R12a·D3 — status is EXPLICIT. The column default is 'sent' (it predates there being any
       send path at all), so omitting it here is what made opening this dialog a lie. */
    const ins = await db.from("fact_finds").insert({ case_id: caseId, client_id: clientId, status: "created", created_by: (ME && ME.id) || null, token: ffToken() }).select("*").single();
    if (ins.error) return toast("Error: " + ins.error.message);
    ff = ins.data;
  } else if (!ff.token) {
    // Legacy row created before tokens were set client-side — back-fill so the link works.
    const tok = ffToken();
    await db.from("fact_finds").update({ token: tok }).eq("id", ff.id);
    ff.token = tok;
  }
  const siteUrl = String(settings.site_url || "").trim();
  const base = (siteUrl || "https://nexmoney.co.uk").replace(/\/$/, "");
  const link = `${base}/factfind?token=${ff.token}`;
  const [badgeCls, badgeBase, badgeTip] = FF_BADGE[ff.status] || ["badge grey", String(ff.status || "unknown"), ""];
  /* R12a·D3 (d) — the badge states WHEN, not just what: "sent" with no date is the same
     unanswerable question the old dialog left behind ("sent when? by whom?").
     fact_finds carries submitted_at but no sent_at, and inventing one client-side would be a
     guess. The date therefore comes from the thing that actually did the sending: the newest
     SENT "factfind" row in email_queue for this case. A row advanced to 'sent' by some other
     route (or before v12 existed) has no such email and simply shows no date — the tooltip says
     why rather than the badge implying one. */
  let sentOn = null;
  if (ff.status === "sent") {
    const ffMails = await softRows(db.from("email_queue").select("sent_at,created_at,status")
      .eq("case_id", caseId).eq("email_type", "factfind").eq("status", "sent"));
    sentOn = ffMails.map((m) => m.sent_at || m.created_at).filter(Boolean).sort().slice(-1)[0] || null;
  }
  /* "sent" carries its date IN the pill, because "sent" on its own is the question, not the
     answer. started/submitted keep exactly the line they always had. */
  const badgeWord = ff.status === "sent" && sentOn ? `sent ${fmtD(sentOn)}` : badgeBase;
  const hasData = ff.status === "submitted" && ff.data && Object.keys(ff.data).length;
  $("#modal").innerHTML = `
    <h3>Digital fact-find</h3>
    <p class="panel-sub">Send this secure link to the client. They fill it in on any device, can save as they go, and you get a task the moment they submit.</p>
    <div style="margin:10px 0;"><span class="${badgeCls}" id="ff-status-badge" title="${esc(badgeTip)}">${esc(badgeWord)}</span>${ff.submitted_at ? " · submitted " + esc(fmtD(ff.submitted_at)) : ""}</div>
    <label>Client link
      <div style="display:flex;gap:8px;">
        <input id="ff-link" readonly value="${esc(link)}" style="flex:1;">
        <button class="btn btn-sm" id="ff-copy">Copy</button>
      </div>
    </label>
    ${siteUrl ? "" : '<p class="dq-notice bad" id="ff-no-site-url" style="margin-top:10px;">No <strong>Site URL</strong> is set in Settings, so there is no address to build the client\'s link from. The link above is a guess and the email cannot be sent until somebody fills that setting in.</p>'}
    <div class="action-bar" style="margin-top:10px;">
      <button class="btn btn-sm btn-primary" id="ff-send">✉️ Send fact-find email</button>
      <button class="btn btn-sm" id="ff-mail" title="Opens a draft in your own email program. Nothing is recorded as sent, because the system cannot see what you do in there.">Open in your email app instead</button>
      <button class="btn btn-sm" id="ff-refresh">↻ Refresh status</button>
      <button class="btn btn-sm" id="ff-new">New blank fact-find</button>
    </div>
    ${hasData ? `<div style="margin-top:16px;"><div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;"><h3 style="font-size:14px;margin:0;">Submitted responses</h3><button class="btn btn-sm btn-primary" id="ff-apply">➡️ Apply to case</button></div>${ffProtInterest(ff.data).interested ? '<p class="panel-sub" style="margin:6px 0 0;color:var(--green);font-weight:600;">💷 Protection interest flagged — capture the cross-sell when you apply.</p>' : ""}${renderFactFindData(ff.data)}</div>`
              : '<p class="panel-sub" style="margin-top:16px;">Responses will appear here once the client submits.</p>'}
    <div class="modal-actions"><div></div><div class="right"><button class="btn" id="ff-back">Back to case</button></div></div>`;
  openModal();
  $("#ff-copy").onclick = () => { const el = $("#ff-link"); el.select(); try { document.execCommand("copy"); } catch (e) {} if (navigator.clipboard) navigator.clipboard.writeText(el.value); toast("Link copied"); };
  $("#ff-back").onclick = () => openCase(caseId);
  if ($("#ff-apply")) $("#ff-apply").onclick = () => ffApplyDiff(caseId, clientId, ff.data);
  $("#ff-refresh").onclick = () => factFind(caseId, clientId);
  $("#ff-new").onclick = async () => {
    if (!confirm("Start a fresh blank fact-find? The current link stops being the active one.")) return;
    // R12a·D3 — same explicit 'created': a brand-new blank fact-find has not been sent either.
    await db.from("fact_finds").insert({ case_id: caseId, client_id: clientId, status: "created", created_by: (ME && ME.id) || null, token: ffToken() });
    factFind(caseId, clientId);
  };
  /* THE REAL SEND. queueEmail does the confirm (naming the signatory), the single email_queue
     insert, the scoped runAutomation that sends exactly that row, the case note and the chase
     task — see its `factfind` branches. Reopening afterwards repaints the badge from whatever
     process-emails actually left on the fact_finds row, rather than assuming success. */
  $("#ff-send").onclick = async (ev) => {
    if (await queueEmail(caseId, clientId, "factfind", kase || { id: caseId }, ev)) factFind(caseId, clientId);
  };
  /* THE mailto, kept and made honest. The sign-off rule is queueEmail's, deliberately duplicated
     in one small helper rather than re-derived, so the two routes can never sign off differently.
     The case note is the point: this is the one send the system genuinely cannot confirm, and the
     note says so in those words rather than implying delivery. */
  $("#ff-mail").onclick = async () => {
    const { data: cl } = await db.from("clients").select("email,first_name,last_name").eq("id", clientId).single();
    if (!cl || !cl.email) return toast("This client has no email address on file — add one first.");
    const signedBy = caseSignOffName(kase);
    const subj = encodeURIComponent(`${settings.company_name || "NexMoney"} — your quick mortgage fact-find`);
    const body = encodeURIComponent(`Hi ${(cl.first_name || "there").trim()},\n\nBefore we speak, please could you complete this short, secure fact-find? It takes about 5–10 minutes and you can save and come back to it:\n\n${link}\n\nThanks,\n${signedBy}`);
    window.open(`mailto:${cl.email}?subject=${subj}&body=${body}`);
    const who = [cl.first_name, cl.last_name].filter(Boolean).join(" ").trim() || cl.email;
    const { error: nErr } = await db.from("case_notes").insert({
      case_id: caseId,
      body: `Fact-find link prepared in your email app for ${who} — the system cannot confirm it was sent. Signed off by ${signedBy}.`,
      created_by: (ME && ME.id) || null,
    });
    toast(nErr
      ? "Draft opened in your email app — but the case note could not be written: " + nErr.message
      : "Draft opened in your email app — the case now says the link was prepared, not sent (we cannot see what happens in there).");
  };
};
/* R12a·D3 — ADV-1's sign-off rule, in one place. The CASE's adviser signs; on an unassigned case a
   non-owner signs in their own name; only then does it fall back to the firm-wide default (which
   is the OWNER's name, and is exactly what made this wrong when anybody else pressed send). */
function caseSignOffName(c) {
  const senderName = ((ME && ME.full_name) || "").trim();
  if (c && c.assigned_to && staffName(c.assigned_to) !== "—") return staffName(c.assigned_to);
  if (!isOwner() && senderName) return senderName;
  return settings.adviser_name || "your firm";
}
function renderFactFindData(data) {
  return `<div class="ff-data">` + Object.keys(data).filter((k) => String(data[k] ?? "").trim() !== "")
    .map((k) => `<div class="ff-row"><span class="ff-k">${esc(prettyFF(k))}</span><span class="ff-v">${esc(data[k])}</span></div>`).join("") + `</div>`;
}
/* ---------- BUILD 4a: fact-find → case "Apply" ----------
   Maps digital fact-find answer keys (from factfind.html) onto the clients/cases columns
   app.js already writes. Only columns already touched elsewhere are used (no schema changes). */
const FF_MAP = [
  { t: "client", col: "first_name",    label: "First name",     ff: ["a1_first"] },
  { t: "client", col: "last_name",     label: "Last name",      ff: ["a1_last"] },
  { t: "client", col: "email",         label: "Email",          ff: ["email"] },
  { t: "client", col: "phone",         label: "Phone",          ff: ["phone"] },
  { t: "client", col: "date_of_birth", label: "Date of birth",  ff: ["a1_dob"] },
  /* R6-35 — "Address" alone was ambiguous on the one screen where the distinction matters most: this
     row is the CLIENT's own home (factfind.html section 1), and the property row below is the
     building being mortgaged. Both are now named for what they are (SM-09). */
  { t: "client", col: "address",       label: "Client address (home)", ff: ["a1_address", "a1_postcode"] },
  /* R6-35 — factfind.html:150 has asked the client "Property address (if known)" (m_property_address)
     since it shipped, and FF_MAP had no entry for it, so the answer sat in fact_finds.data and never
     reached the case — on the very day the column to hold it arrived. `prop: true` marks the row as
     needing M7: it is filtered out of the diff on a database that has no property column, so nothing
     offers an Apply whose write could only 42703. */
  { t: "case",   col: "property_address", label: "Property address (security)", ff: ["m_property_address"], prop: true },
  { t: "case",   col: "loan_amount",    label: "Loan amount",    ff: ["m_loan"],  num: true, money: true },
  { t: "case",   col: "property_value", label: "Property value", ff: ["m_value"], num: true, money: true },
  { t: "case",   col: "term_years",     label: "Term (years)",   ff: ["m_term"],  num: true },
];
// Protection cross-sell signal from the fact-find protection section (section 7 of factfind.html).
function ffProtInterest(d) {
  d = d || {};
  const reasons = [];
  if (String(d.p_review || "").toLowerCase() === "yes") reasons.push("Asked for a protection review");
  if (String(d.p_life || "").toLowerCase() === "no") reasons.push("No life cover in place");
  if (String(d.p_ip || "").toLowerCase() === "no") reasons.push("No income protection / critical illness cover");
  return { interested: reasons.length > 0, reasons };
}
window.ffApplyDiff = async function (caseId, clientId, data) {
  data = data || {};
  let cRow, clRow;
  try {
    const [rc, rcl] = await Promise.all([
      db.from("cases").select("*").eq("id", caseId).single(),
      db.from("clients").select("*").eq("id", clientId).single(),
    ]);
    cRow = rc.data; clRow = rcl.data;
  } catch (e) { return toast("Could not load case/client to apply"); }
  if (!cRow || !clRow) return toast("Could not load case/client to apply");
  notePropAddrFromStarRow(cRow);
  const ffPropOn = await propAddrSupported();

  const rows = [];
  FF_MAP.forEach((m, i) => {
    if (m.prop && !ffPropOn) return;   // no property column on this database — don't offer the row
    const ffRaw = m.ff.map((k) => String(data[k] == null ? "" : data[k]).trim()).filter(Boolean).join(", ");
    if (!ffRaw) return; // no fact-find answer to apply for this field
    const ffVal = m.num ? Number(String(ffRaw).replace(/[^0-9.]/g, "")) : ffRaw;
    if (m.num && !isFinite(ffVal)) return;
    const src = m.t === "client" ? clRow : cRow;
    const curRaw = src[m.col];
    const curEmpty = curRaw == null || String(curRaw).trim() === "";
    /* R6-35 — an address is "the same" when it is the same BUILDING, not the same string:
       "8 Grand Avenue, Bournemouth BH6 3SY" and "8 Grand Avenue, Southbourne, Bournemouth BH6 3SY"
       are one flat, and proposing to rewrite one as the other is noise. propKey decides. */
    const equal = !curEmpty && (m.prop
      ? propKey(String(curRaw)) === propKey(String(ffVal))
      : (m.num ? Number(curRaw) === ffVal : String(curRaw).trim() === String(ffVal).trim()));
    if (equal) return; // already matches — nothing to do
    const disp = (v) => (v === "" || v == null ? '<span class="cs-muted">— empty —</span>' : (m.money ? esc(fmtM(v)) : esc(v)));
    rows.push({
      idx: i, m, ffVal, conflict: !curEmpty, checked: curEmpty,
      // A property conflict is not a typo to reconcile — it means the client has named a DIFFERENT
      // building from the one on the case. It is called out as such, and stays unticked.
      propMismatch: !!(m.prop && !curEmpty),
      curHtml: disp(curEmpty ? "" : curRaw), ffHtml: disp(m.num ? ffVal : ffRaw),
    });
  });

  const prot = ffProtInterest(data);
  const curProt = cRow.protection_status || "not_discussed";
  const protUpgradeable = prot.interested && curProt === "not_discussed";

  const tableRows = rows.map((r) => `
    <tr>
      <td style="padding:6px 8px;font-weight:600;">${esc(r.m.label)}<div class="cs-muted" style="font-weight:400;font-size:11px;">${r.m.t}</div></td>
      <td style="padding:6px 8px;">${r.curHtml}</td>
      <td style="padding:6px 8px;">${r.ffHtml}${r.conflict ? ' <span class="badge amber" style="margin-left:4px;">conflict</span>' : ""}${r.propMismatch ? ' <span class="badge red" style="margin-left:4px;" title="The client has named a different building from the one on this case. Check which is right before applying — one of them belongs to a different case.">different property</span>' : ""}</td>
      <td style="padding:6px 8px;text-align:center;"><input type="checkbox" id="ffchk-${r.idx}" ${r.checked ? "checked" : ""} style="width:auto;"></td>
    </tr>`).join("");

  const protBox = prot.interested ? `
    <div style="margin-top:14px;border:1px solid var(--green);background:rgba(23,114,69,.07);border-radius:10px;padding:12px;">
      <div style="font-weight:700;color:var(--green);">💷 Protection cross-sell opportunity</div>
      <ul style="margin:6px 0 8px;padding-left:18px;font-size:13px;">${prot.reasons.map((x) => `<li>${esc(x)}</li>`).join("")}</ul>
      <label class="row-check" style="display:flex;gap:8px;align-items:flex-start;font-size:13px;font-weight:600;">
        <input type="checkbox" id="ff-prot-chk" ${protUpgradeable ? "checked" : ""} style="width:auto;margin-top:2px;">
        Flag protection ${protUpgradeable ? "" : "(current: " + esc(curProt.replace(/_/g, " ")) + ") "}and create a follow-up task for the adviser
      </label>
    </div>` : "";

  $("#modal").innerHTML = `
    <h3>Apply fact-find to case</h3>
    ${/* R6-35 — the modal wrote to ONE case and named none of them: on a client with six cases the
          adviser could not see which record was about to change (SM-09). */ ""}
    <p class="panel-sub" style="margin-bottom:2px;">${esc([clRow.first_name, clRow.last_name].filter(Boolean).join(" ") || "This client")} — ${caseIdentityHtml(cRow, { fallback: true })}</p>
    <p class="panel-sub">Tick what to copy from the client's answers onto the case & client record. Empty fields are pre-ticked; values that would overwrite existing data start unticked. “Client address (home)” is where the client lives; “Property address (security)” is the building this case is secured on — they are different fields and a fact-find can disagree with the case about either.</p>
    ${rows.length ? `
    <table style="width:100%;border-collapse:collapse;font-size:13px;margin-top:8px;">
      <thead><tr style="text-align:left;border-bottom:1px solid var(--line);">
        <th style="padding:6px 8px;">Field</th><th style="padding:6px 8px;">Current</th><th style="padding:6px 8px;">Fact-find</th><th style="padding:6px 8px;text-align:center;">Apply</th>
      </tr></thead>
      <tbody>${tableRows}</tbody>
    </table>` : '<p class="panel-sub" style="margin-top:8px;">Every mapped field already matches the case — nothing to copy.</p>'}
    ${protBox}
    <div class="modal-actions">
      <div></div>
      <div class="right">
        <button class="btn" id="ff-apply-back">Back</button>
        <button class="btn btn-primary" id="ff-apply-confirm">Apply ticked fields</button>
      </div>
    </div>`;
  openModal();
  $("#ff-apply-back").onclick = () => factFind(caseId, clientId);
  $("#ff-apply-confirm").onclick = async () => {
    const btn = $("#ff-apply-confirm");
    if (btn) { if (btn.disabled) return; btn.disabled = true; }
    try {
      const clientUpd = {}, caseUpd = {};
      let n = 0;
      rows.forEach((r) => {
        const chk = $("#ffchk-" + r.idx);
        if (!chk || !chk.checked) return;
        (r.m.t === "client" ? clientUpd : caseUpd)[r.m.col] = r.ffVal;
        n++;
      });
      const protChk = $("#ff-prot-chk");
      const doProt = !!(protChk && protChk.checked);
      // Only upgrade protection_status from the default; never clobber a more advanced status.
      if (doProt && (cRow.protection_status || "not_discussed") === "not_discussed") caseUpd.protection_status = "discussed";
      if (!n && !doProt) { toast("Nothing ticked to apply"); return; }
      if (Object.keys(clientUpd).length) {
        const { error } = await db.from("clients").update(clientUpd).eq("id", clientId);
        if (error) { toast("Error: " + error.message); return; }
      }
      if (Object.keys(caseUpd).length) {
        const { error } = await db.from("cases").update(caseUpd).eq("id", caseId);
        if (error) { toast("Error: " + error.message); return; }
      }
      let uid = (ME && ME.id) || null;
      try { const { data: { user } } = await db.auth.getUser(); if (user && user.id) uid = user.id; } catch (e) {}
      let body = `Fact-find applied: ${n} field${n === 1 ? "" : "s"} updated`;
      if (doProt) body += " · protection interest flagged";
      let protTaskNote = "";
      if (doProt) {
        // Defect 11: don't stack a second protection follow-up on top of one that's already open —
        // check for an existing open task with the same "Protection:" title prefix on this case first.
        const { data: openTasks } = await db.from("case_tasks").select("id,title").eq("case_id", caseId).is("done_at", null);
        const existingProtTask = (openTasks || []).find((t) => (t.title || "").startsWith("Protection:"));
        if (existingProtTask) {
          protTaskNote = " · existing protection task kept";
        } else {
          // Due TODAY: a fresh cross-sell interest deserves a same-day call, and a
          // today-dated task surfaces immediately on the My Day hero list.
          const due = localDateStr(Date.now());
          await db.from("case_tasks").insert({
            case_id: caseId, title: "Protection: client expressed interest in fact-find", due_date: due,
            created_by: uid, assigned_to: cRow.assigned_to || uid,
          });
          protTaskNote = " · protection task created";
        }
      }
      await db.from("case_notes").insert({ case_id: caseId, body, created_by: uid });
      toast(`Applied ${n} field${n === 1 ? "" : "s"}${protTaskNote}`);
      openCase(caseId); // re-renders the case modal summary with the updated values, note & task
    } catch (e) {
      toast("Error applying fact-find: " + (e && e.message ? e.message : e));
    } finally {
      if (btn) btn.disabled = false;
    }
  };
};
// Fact-find key -> human label (defect 25, label half). Only strips a namespace prefix when it's
