    <tr class="rb-total-row"><td><strong>Next 24 months</strong></td><td><strong>${m.n}</strong></td><td><strong>${fmtM(m.loan)}</strong></td><td><strong>${fmtM(m.fee)}</strong></td><td><strong>${fmtM(m.fee)}</strong></td></tr>
